<h2>مسیر دورود به دریاچه گهر؛ از شهر تا شروع پیمایش</h2>
<p>مسیر متداول دسترسی از شهرستان دورود آغاز می‌شود. ابتدا باید خودتان را با خودرو شخصی، اتوبوس یا قطار به دورود برسانید. از دورود، مسیر جاده‌ای به سمت درب آستانه، امامزاده پیر والی و چشمه خیه یا چشمه خرم ادامه پیدا می‌کند. در منابع مختلف، طول جاده آسفالته از دورود تا محدوده شروع پیمایش حدود ۱۷ تا ۲۴ کیلومتر ذکر شده است؛ این اختلاف به محل دقیق شروع، نام‌گذاری محلی و نقطه پارک خودرو برمی‌گردد.</p>
<p>پس از رسیدن به پارکینگ/ورودی مسیر، بخش اصلی سفر آغاز می‌شود: پیاده‌روی در مسیر کوهستانی. برخی منابع رسمی مسیر مالرو از چشمه خیه تا گهر را حدود ۱۸ کیلومتر نوشته‌اند؛ در تجربه‌های محلی و برخی گزارش‌های مسیر، عدد حدود ۱۲٫۵ تا ۱۳ کیلومتر هم برای پیمایش اصلی دیده می‌شود. بنابراین بهتر است برای برنامه‌ریزی محافظه‌کارانه، مسیر را کوتاه فرض نکنید و آمادگی پیمایش ۱۳ تا ۱۸ کیلومتر کوهستانی را داشته باشید.</p>

<h2>نام‌های محلی و نقاط مهم مسیر</h2>
<p>در مسیر دورود به گهر، نام‌هایی مثل چشمه خیه، چشمه خرم، گردنه پنبه‌کار، گردنه خداقوت، روستای سراوند، روستای تیتی، دره نی‌گاه یا نگار و گهررود شنیده می‌شود. همه این نام‌ها برای مسیریابی عمومی کافی نیستند، چون مسیرهای مالرو و فرعی می‌توانند انشعاب داشته باشند. اگر بار اول است که می‌روید، فقط به دنبال‌کردن جمعیت اکتفا نکنید؛ نقشهٔ آفلاین و همراهی راهنمای محلی یا فرد آشنا با مسیر، به مسیریابی و تصمیم‌گیری ایمن کمک می‌کند.</p>
<p>گردنه پنبه‌کار معمولاً سخت‌ترین بخش مسیر معرفی می‌شود. این بخش هم شیب دارد، هم زیر آفتاب می‌تواند فرساینده شود، و هم در برگشت فشار بیشتری به زانو و توان بدنی وارد می‌کند. اگر کوله سنگین دارید، وزن و تقسیم بار را پیش از حرکت بازبینی کنید. دربارهٔ امکان و شرایط خدمات مجاز حمل بار محلی از مسئول یا راهنمای مورد اعتماد بپرسید؛ دسترسی به این خدمات را در همهٔ روزها قطعی فرض نکنید.</p>

