<p>وقتی نام «پایتخت طبیعت ایران» به میان می‌آید، <a href="/city/dorud/">شهرستان دورود</a> در شرق <a href="/province/lorestan/">استان لرستان</a> نخستین مقصدی است که در ذهن هر طبیعت‌گردی می‌درخشد<sup class="sa-cite"><a href="https://www.visitiran.ir/fa/destination/%D8%AF%D9%88%D8%B1%D9%88%D8%AF">۱</a></sup>. شهری نشسته در آغوش دشت حاصلخیز سیلاخور و پای دیواره‌های برف‌گیر اشترانکوه، جایی که دو رود تیره و ماربره به هم می‌رسند تا رود خروشان سزار را بسازند و خط آهن تاریخی سراسری از دل تونل‌ها و دره‌هایش بگذرد. از <a href="/attraction/gahar-lake-dorud/">دریاچهٔ گهر</a> و <a href="/attraction/bisheh-waterfall-dorud/">آبشار بیشه</a> تا <a href="/attraction/tangeh-lili-gorge-doroud/">تنگه لی لی</a> و <a href="/attraction/nigah-valley-dorud/">دره نی‌گاه</a>، دورود کلکسیونی از متنوع‌ترین چشم‌اندازهای آبی و کوهستانی زاگرس است.</p>

<h2>دورود چرا در نقشهٔ سفر ایران جایگاهی ویژه دارد؟</h2>
<p>در سرشماری عمومی نفوس و مسکن ۱۳۹۵، جمعیتِ شهر دورود ۱۲۱٬۶۳۸ نفر ثبت شده است<sup class="sa-cite"><a href="https://amar.org.ir/population-and-housing-census">۲</a></sup>. مزیت بزرگ دورود برای مسافر این است که در شعاع چند ده کیلومتری یک شهر با دسترسی هم‌زمانِ ریلی و جاده‌ای، هم مقصدهای آسان خانوادگی و هم مسیرهای ماجراجویانهٔ کوهستانی کنار هم چیده شده‌اند<sup class="sa-cite"><a href="https://www.visitiran.ir/fa/province/%D8%A7%D8%B3%D8%AA%D8%A7%D9%86-%D9%84%D8%B1%D8%B3%D8%AA%D8%A7%D9%86">۳</a></sup>. در شهرستان دورود، دیدنی‌هایی مانند دریاچهٔ کوهستانی، آبشارها، دره‌ها، غار، تالاب فصلی، پارک جنگلی و روستاهای کوهستانی قرار دارند. راه‌آهن و جاده نیز شهر را به محورهای <a href="/province/lorestan/">لرستان</a> و برخی مقصدهای اطراف پیوند می‌دهند. دسترسی، دشواری و شرایط بازدید در هر مقصد متفاوت است.</p>
<p>انتخاب مقصد در دورود به زمان، توان پیمایش، فصل و دسترسی بستگی دارد. برای برنامهٔ کوتاه، گزینه‌های نزدیک شهر را جداگانه بررسی کنید؛ گهر، نی‌گاه، شوی و غارها به برنامه‌ریزی و آمادگی بیشتری نیاز دارند. شرایط نور و پوشش گیاهی نیز در طول سال تغییر می‌کند.</p>

<h2>شناخت سریع جاذبه‌های دورود</h2>
<ul>
<li><strong>شاخص‌ترین مقصد کوهستانی:</strong> دریاچه گهر در منطقه حفاظت‌شده اشترانکوه.</li>
<li><strong>شاخص‌ترین آبشارهای سفر:</strong> بیشه، شوی/تله‌زنگ، آب‌گرمه، <a href="/attraction/aznadar-waterfall-doroud/">ازنادر</a>، حشوید/هشوید و عزیزآباد.</li>
<li><strong>بهترین مسیرهای دره‌ای:</strong> دره نی‌گاه، دره اسپر، دره شوی و <a href="/attraction/tangeh-lili-gorge-doroud/">تنگه لی لی (سورپیلو)</a>.</li>
<li><strong>دیدنی‌های غاری و کوهستانی:</strong> غار منو، غار وقت ساعت، غار مرده‌ها/مردگان، کوه قارون و <a href="/attraction/azgan-wetland-dorud/">تالاب ازگن</a>.</li>
<li><strong>گزینه‌های نزدیک‌تر برای خانواده:</strong> پارک دانشجو، پارک جنگلی باباهور، بلندی باباهور و مسیرهای سبک اطراف شهر.</li>
</ul>

<h2>دریاچه گهر؛ نگین فیروزه‌ای اشترانکوه</h2>
<p>دریاچهٔ گهر از مقصدهای شاخص طبیعی شهرستان دورود است؛ دریاچه‌ای کوهستانی در منطقهٔ حفاظت‌شدهٔ اشترانکوه که منابع گردشگری فاصلهٔ آن را حدود ۳۵ کیلومتر در جنوب‌شرقی دورود ذکر می‌کنند. ارتفاع دریاچه حدود ۲۳۵۰ متر است و وسعت آن در منابع مختلف نزدیک به ۸۸ تا ۱۰۰ هکتار آمده است. این اختلاف عددی برای کاربر نهایی مهم‌تر از اصل موضوع نیست: گهر یک مقصد جدی طبیعت‌گردی است، نه یک توقف کوتاه کنار جاده.</p>
<p>مسیر رایج دسترسی، از دورود به سمت درب آستانه و چشمه خیه است و بعد از آن پیاده‌روی/مسیر مالرو آغاز می‌شود. در فصل‌های شلوغ، باید وضعیت محیط‌زیست، امکان کمپ، حمل بار، آب‌وهوا و ظرفیت منطقه بررسی شود. برای خانواده‌ها، سفر به گهر زمانی لذت‌بخش است که برنامه رفت‌وبرگشت، کفش مناسب، لباس گرم و توان پیاده‌روی در نظر گرفته شده باشد.</p>

<h2>آبشارهای دورود؛ از بیشه تا مسیرهای بکرتر</h2>
<h3>آبشار بیشه یا پوران</h3>
<p>آبشار بیشه با مسیر ریلی، روستای بیشه، پل و جنگل‌های بلوط یکی از خواناترین مقصدهای لرستان است. در منابع رسمی، فاصله آن حدود ۳۰ کیلومتر از دورود و حدود ۶۵ کیلومتر از خرم‌آباد ذکر شده و ارتفاع آبشار حدود ۵۸ متر آمده است. برای بازدید از بیشه می‌توان مسیر ریلی دورود و ایستگاه نزدیک آبشار را بررسی کرد؛ ساعت قطار و وضعیت مسیر پیاده‌روی را پیش از حرکت بسنجید.</p>

<h3>آبشار شوی یا تله‌زنگ</h3>
<p>آبشار شوی یا تله‌زنگ در نزدیکی روستای شوی، در بخش شهیونِ شهرستان دزفول و استان خوزستان قرار دارد. مسیر ریلی از ایستگاه تله‌زنگ در محور دورود–اندیمشک می‌گذرد؛ از همین رو این آبشار در برنامه‌های سفرِ آغازشونده از دورود هم مطرح می‌شود، هرچند خودِ ریزشگاه در شهرستان دورود نیست.</p>

<h3>آبشار آب‌گرمه یا چم‌چیت</h3>
<p>آبشار آب‌گرمه، که با چم‌چیت هم شناخته می‌شود، آبشاری کمتر شلوغ و نزدیک مسیر رود سزار است. در فهرست محلی، فاصله آن حدود ۲۳ کیلومتر در جنوب غربی دورود آمده و ارتفاع آن بیش از ۲۰ متر و عرض تاج حدود ۱۰ متر ذکر شده است. بهترین زمان بازدید معمولاً از فروردین تا آبان است، اما در روزهای بارانی یا مسیرهای لغزنده باید احتیاط کرد.</p>

<h3><a href="/attraction/aznadar-waterfall-doroud/">آبشار ازنادر/اذنادر و دره اسپر</a></h3>
<p>آبشار ازنادر در نزدیکی روستای گردشگری دره اسپر قرار می‌گیرد و معمولاً به‌عنوان آبشاری فصلی و مناسب طبیعت‌گردی سبک‌تر معرفی می‌شود. دره اسپر حدود ۷ کیلومتر با دورود فاصله دارد و به دلیل چشمه‌های دائمی و فصلی، روستا، چشم‌انداز سبز و مسیرهای کوتاه پیاده‌روی، برای کسانی که می‌خواهند از شهر خیلی دور نشوند انتخاب خوبی است.</p>

<h3>آبشار حشوید/هشوید، دوش خرسان و عزیزآباد</h3>
<p>حشوید یا هشوید از آبشارهای بکرتر دورود است و در نزدیکی روستای حشوید و دشت سیلاخور معرفی می‌شود. دوش خرسان در محدوده دره خرس و مسیرهای دره نی‌گاه قرار دارد و برای طبیعت‌گردی با سختی متوسط مناسب‌تر است. آبشار و تنگه عزیزآباد نیز در نزدیکی چالانچولان و حاشیه دشت سیلاخور، با چشمه‌ها و آبشارهای متعدد شناخته می‌شوند. برای این نقاط، راهنمای محلی و بررسی مسیر، مخصوصاً بعد از بارندگی، ضروری است.</p>

<h2>دره‌ها، روستاها و مسیرهای بکر</h2>
<p>دره نی‌گاه، که گاهی با املای نگار هم دیده می‌شود، از مسیرهای کوهستانی و دورافتادهٔ شهرستان دورود است. دیواره‌های صخره‌ای و بستر رودخانه از ویژگی‌های چشم‌انداز آن‌اند؛ طول و نقطهٔ آغاز پیمایش در گزارش‌ها یکسان نیست و باید مسیر دقیق و شرایط روز را پیش از حرکت با راهنمای محلی بررسی کرد.</p>


<h2>کوه‌ها، تالاب‌ها و غارهای دورود</h2>
<p>کوه قارون یکی از نشانه‌های طبیعی جنوب دورود است؛ کوهی منفرد و دیدنی که در برخی فهرست‌های گردشگری ارتفاع آن حدود ۲۵۵۰ متر ذکر شده است؛ زمان و امکان صعود به وضعیت هوا و مسیر بستگی دارد. <a href="/attraction/azgan-wetland-dorud/">تالاب ازگن یا قارون</a> نیز تالابی فصلی در دامنه کوه پریز و کوه قارون است که معمولاً تا اواخر بهار آب دارد و سپس خشک می‌شود؛ راهنمای کامل آن در صفحه تالاب ازگن آمده است. <a href="/attraction/tangeh-lili-gorge-doroud/">تنگه لی لی (سورپیلو)</a> هم در حدود ۲۰ کیلومتری شرق دورود، بین روستاهای چمنار و سیره، دره‌ای صخره‌ای با حوضچه‌های طبیعی و کتیبه یونانی است.</p>
<p>غار منو نزدیک روستای گورکش، غار وقت ساعت در دامنه جنوبی کوه پریز و نزدیک ایستگاه راه‌آهن چم‌چید، و غار مرده‌ها یا مردگان نزدیک روستای دریژان از غارهای مطرح دورود هستند. نکته مشترک همه این غارها این است که نباید مثل یک مقصد تفریحی ساده با آن‌ها برخورد کرد. چراغ، کفش مناسب، همراه باتجربه، راهنمای محلی و پرهیز از ورود در بارندگی یا تاریکی، حداقل احتیاط لازم است.</p>

<h2>فضاهای شهری و خانوادگی</h2>
<p>همه سفرهای دورود قرار نیست سنگین و کوهستانی باشند. پارک دانشجو در مرکز شهر، با فضای سبز خطی، مسیرهای پیاده‌روی و دسترسی ساده، برای توقف کوتاه، خانواده و استراحت شهری مناسب است. پارک جنگلی باباهور و بلندی باباهور نیز با درختان بلوط، مسیر پیاده‌روی و چشم‌انداز دامنه‌ای، گزینه‌ای نزدیک‌تر برای گردش سبک به‌شمار می‌آیند. سراب رودک، در نزدیکی ایستگاه راه‌آهن رودک، هم می‌تواند در برنامه‌های کوتاه‌تر بررسی شود.</p>

<h2>فهرست مرتب جاذبه‌های دورود</h2>
<table>
