<p><strong>تنگه لی لی</strong> که در گویش محلی با نام <strong>تنگه سورپیلو</strong> هم شناخته می‌شود، یکی از شگفت‌انگیزترین دره‌های صخره‌ای در حدود ۲۰ کیلومتری شرق <a href="/city/dorud/">دورود</a> است<sup class="sa-cite"><a href="https://www.irandeserts.com/article/%D8%AA%D9%86%DA%AF%D9%87-%D9%84%DB%8C-%D9%84%DB%8C-%D8%AF%D9%88%D8%B1%D9%88%D8%AF/">۱</a></sup>؛ جایی که رود زلال ماربره در گذر هزاران سال، صخره‌های آهکی زاگرس را تراشیده و تنگه‌ای باریک با دیواره‌های صیقلی، حوضچه‌های پلکانی و حتی یادگاری دوهزارساله از دوران باستان (کتیبهٔ یونانی تنگه لی‌لی) پدید آورده است<sup class="sa-cite"><a href="https://iranohellenica.eie.gr/content/catalogue/tang-e-lili">۲</a></sup>. قرار گرفتن تنگه میان دو روستای چمنار و سیره، دسترسی به آن را برای یک برنامهٔ نیم‌روزه یا یک‌روزه بسیار جذاب می‌کند.</p>
<p>حوضچه‌های طبیعی و بستر رود ماربره بخشی از چشم‌انداز تنگه‌اند. شکل و عمق آب با بارندگی و فصل تغییر می‌کند؛ ورود به آب یا استفاده از قایق را بدون تأیید مقررات و شرایط ایمن همان روز، مجاز یا بی‌خطر فرض نکنید. کتیبه‌ای یونانی روی صخره‌ای آهکی مشرف به تنگه نیز به این ناحیه بُعد تاریخی می‌دهد.</p>
