<h2>چرا تنگه لی لی دیدنیِ شاخص دورود است؟</h2>
<ul>
<li><strong>دره‌ای صخره‌ای با فرسایش طبیعی منحصربه‌فرد:</strong> تنگه در اثر جریان مداوم آب و وزش باد در طول هزاران سال شکل گرفته؛ فرسایش صخره‌ها سطوح صیقلی و دیواره‌هایی با اشکال چشمگیر پدید آورده که لی لی را از سایر تنگه‌های منطقه متمایز می‌کند.</li>
<li><strong>حوضچه‌های طبیعی:</strong> رود ماربره در مسیر عبور از تنگه حوضچه‌هایی ساخته است؛ شکل، عمق و جریان آب با فصل و بارندگی تغییر می‌کند.</li>
<li><strong>پیشینه تاریخی با کتیبه یونانی:</strong> یک کتیبه یونانی به خط و زبان یونان باستان در این تنگه شناسایی شده که قدمت آن به حدود ۱۰۰ پیش از میلاد تا ۱۰۰ میلادی بازمی‌گردد؛ سطح کتیبه روی یک صخره آهکی مسطح و در ارتفاع حدود ۱۶۰۳ متری حک شده است.</li>
<li><strong>تنوع پوشش گیاهی و جانوری:</strong> درختان بلوط، بادام کوهی و زالزالک همراه گیاهان دارویی مانند آویشن، گل گاوزبان و نعنا؛ حیات وحش منطقه هم شامل بز کوهی، میش، روباه و خزندگانی مانند مار می‌شود.</li>
<li><strong>دسترسی خودرویی تا نزدیکی ورودی:</strong> برخلاف بسیاری از جاذبه‌های طبیعی منطقه، می‌توان با خودرو تا نزدیکی ورودی تنگه رفت و باقی مسیر را با پیاده‌روی متوسط (حدود ۴۵ دقیقه از چمنار) طی کرد.</li>
</ul>

{{GALLERY:gorge}}

<h2>تنگه لی لی کجاست؟</h2>
<p>تنگه لی لی در <a href="/province/lorestan/">استان لرستان</a>، <a href="/city/dorud/">شهرستان دورود</a> و حدود ۲۰ کیلومتری شرق این شهرستان، در مجاورت روستای چمنار از توابع بخش مرکزی و دهستان حشمت‌آباد و نرسیده به روستای سیره (لاسوره) قرار دارد. مختصات تقریبی آن در منابع محلی N۳۳ ۲۶ E۴۹ ۱۲ گزارش شده و پروژه کاتالوگ کتیبه‌های یونانی ایران برای محل کتیبه، مختصات ۳۳٫۴۲۲۶ و ۴۹٫۱۷۱۷ را ثبت کرده است. تنگه در غرب <a href="/attraction/gahar-lake-dorud/">دریاچه گهر</a> و قله اشترانکوه قرار می‌گیرد و رود ماربره پس از عبور از آن، به سمت شمال و شهر دورود می‌رود و در نهایت به رود سزار می‌پیوندد.</p>
<p>درباره نام: «لی لی» نامی است که اهالی محل به این تنگه داده‌اند؛ در منطقه درختان گیلاس وجود دارد و محلی‌ها به گیلاس‌های ریز «لی لی» می‌گویند. نام «سورپیلو» هم از پلی به همین نام در نزدیکی تنگه گرفته شده است. در متن منابع، نام روستای نزدیک به تنگه به شکل‌های چمنار (چمنار)، سیره/لاسوره و سیرم ثبت شده است؛ اگر با راهنمای محلی حرکت کنید، این نام‌ها در مسیر برایتان روشن می‌شود.</p>

<h2>مسیر دسترسی؛ از دورود تا ورودی تنگه</h2>
<p>وضعیت جاده‌های فرعی و مسیرهای پیاده‌روی بسته به بارش‌های فصلی و شرایط محلی تغییر می‌کند؛ پرس‌وجو از اهالی روستای چمنار پیش از حرکت توصیه می‌شود.</p>
<h3>۱) با خودرو از دورود (مسیر اصلی)</h3>
<p>از شهر دورود وارد جادهٔ قدیم ازنا–دورود شوید و مسیر چمنار را دنبال کنید. برخی راهنماها فاصلهٔ جاده‌ای دورود تا روستا را نزدیک به ۱۴ کیلومتر و پیاده‌روی تا تنگه را حدود ۴۵ دقیقه برآورد می‌کنند؛ زمان واقعی با مبدأ دقیق و وضعیت مسیر تغییر می‌کند. خودرو تا نزدیکی ورودی می‌رسد، اما بخش‌هایی از تنگه ناهموار و صخره‌ای‌اند.</p>
<h3>۲) از خرم‌آباد و شهرهای همسایه</h3>
<p>از <a href="/city/khorramabad/">خرم‌آباد</a> به سمت <a href="/city/borujerd/">بروجرد</a> و سپس دورود حرکت کنید؛ فاصله خرم‌آباد تا تنگه لی لی حدود ۱۰۰ کیلومتر و حدود دو ساعت است.</p>
<h3>۳) از تهران</h3>
<p>مسیر تهران – سلفچگان – اراک – بروجرد – دورود – تنگه لی لی حدود ۶۰۰ کیلومتر و حدود ۸ ساعت زمان می‌برد. مسیر جایگزین از ساوه – همدان – ملایر – بروجرد هم حدود ۶۵۰ کیلومتر است.</p>
<h3>۴) با قطار و اتوبوس</h3>
<p>نزدیک‌ترین ایستگاه راه‌آهن، ایستگاه دورود است؛ از آنجا با تاکسی یا وسایل حمل‌ونقل محلی به سمت روستای چمنار بروید. از شهرهای بزرگ ایران هم اتوبوس‌هایی به خرم‌آباد و دورود رفت‌وآمد می‌کنند و ادامه مسیر با تاکسی یا اتوبوس‌های محلی انجام می‌شود.</p>

<h2>جدول مقایسهٔ دو مسیر اصلی دسترسی به آبشار شوی</h2>
<table>
<thead><tr><th>مسیر دسترسی</th><th>مبدأ حرکت</th><th>مسافت و زمان پیاده‌روی</th><th>ویژگی‌ها و الزامات</th></tr></thead>
<tbody>
<tr><td>مسیر اول: ریلی از ایستگاه تله‌زنگ (شهید چراغی)</td><td>قطار محلی <a href="/city/dorud/">دورود</a> یا <a href="/city/andimeshk/">اندیمشک</a></td><td>حدود ۱۰ تا ۱۲ کیلومتر کوه‌پیمایی از ایستگاه (۳ تا ۴ ساعت هر طرف)</td><td>مسیر کلاسیک در امتداد دره و رود؛ بدون آنتن موبایل و نیازمند <a href="/gps-navigation-tools/">مسیریابی آفلاین</a></td></tr>
<tr><td>مسیر دوم: جاده‌ای از بخش شهیون دزفول</td><td><a href="/city/dezful/">دزفول</a> ← سردشت ← شهیون ← پیرچل ← روستای شوی</td><td>حدود ۱۰۰ کیلومتر جاده کوهستانی + ۲ تا ۳ ساعت پیاده‌روی از پارکینگ روستا</td><td>مسیر پیاده‌روی کوتاه‌تر اما جاده پرپیچ‌وخم؛ عبور از تنگه پیرچل با پله و دستگیرهٔ فلزی</td></tr>
</tbody>
</table>

<h2>بهترین زمان بازدید</h2>
<ul>
<li><strong>بهار (فروردین تا خرداد):</strong> طبیعت اطراف معمولاً سرسبزتر است؛ بارندگی و افزایش جریان آب می‌تواند مسیر را لغزنده یا ناایمن کند. پیش از حرکت، شرایط روز را بررسی کنید و وارد آب نشوید.</li>
<li><strong>تابستان (تیر تا شهریور):</strong> گرمای روز می‌تواند شدید باشد؛ برای پیاده‌روی ساعات خنک‌تر را انتخاب کنید و وضعیت آب‌وهوا و مسیر را پیش از حرکت بسنجید.</li>
<li><strong>پاییز (مهر تا آبان):</strong> تا اوایل پاییز امکان بازدید وجود دارد و مناظر پاییزی منطقه دیدنی است؛ لباس گرم همراه ببرید.</li>
<li><strong>زمستان:</strong> به دلیل کوهستانی بودن منطقه و سردسیر بودن دورود، سفر به تنگه در زمستان توصیه نمی‌شود.</li>
</ul>
{{GALLERY:pools}}


<h2>حوضچه‌های طبیعی و نکات بازدید</h2>
<p>آب حوضچه‌ها و جریان رودخانه با فصل و بارندگی تغییر می‌کند و کف سنگی می‌تواند بسیار لغزنده باشد. ظاهر آرام آب یا کم‌عمق به‌نظررسیدن آن، نشانهٔ ایمنی نیست؛ در این راهنما ورود به آب و قایق‌سواری توصیه نمی‌شود. هشدارهای محلی را جدی بگیرید و در صورت نامطمئن‌بودن شرایط، از حاشیهٔ امن مسیر بازدید کنید.</p>

<h2>کتیبه یونانی؛ دو هزار سال تاریخ در دل تنگه</h2>
<p>لی لی یک تنگه معمولی نیست: کتیبه‌ای یونانی روی صخره‌ای آهکی مسطح مشرف به تنگه شناسایی شده که در کاتالوگ پروژه «ایرانوهلنیکا» (بنیاد پژوهش‌های تاریخی آتن، ذیل پروژه نقشه‌برداری برخوردهای فرهنگی یونان و ایران) ثبت شده است<sup class="sa-cite"><a href="https://iranohellenica.eie.gr/content/catalogue/tang-e-lili">۲</a></sup>. قدمت این کتیبه در بازه حدود ۱۰۰ پیش از میلاد تا ۱۰۰ میلادی (دوران اشکانی/سلوکی) تخمین زده می‌شود؛ همین بازه در مقاله علمی منتشرشده در مجله ZPE (شماره ۲۲۸، سال ۲۰۲۳) و گزارش‌های میراث فرهنگی<sup class="sa-cite"><a href="https://www.chtn.ir/news/1403112501893/">۳</a></sup> برای این سنگ‌نوشته گزارش شده است. سطح کتیبه روی صخره‌ای آهکی مسطح و بر پایه گزارش‌های محلی در ارتفاع حدود ۱۶۰۳ متری قرار دارد و ابعاد سطح نوشته‌شده در کاتالوگ حدود ۰٫۴۳ متر ارتفاع و ۰٫۶۳ تا ۰٫۶۹ متر طول ثبت شده است.</p>
<p>اهمیت این کتیبه در دوری آن از شهرها و مسیرهای باستانی اصلی است؛ این سنگ‌نوشته در دل کوهستان زاگرس و در دل همان تنگه‌ای حک شده که امروز مقصد طبیعت‌گردی است. اگر در تنگه با چنین آثاری روبه‌رو شدید، از تماس فیزیکی، مالیدن، تراشیدن یا انداختن زباله در پای آن خودداری کنید و هر اثر تخریبی را به منابع محلی و میراث فرهنگی اطلاع دهید.</p>

{{GALLERY:marbreh}}

<h2>گیاهان و حیات وحش</h2>
<p>پوشش گیاهی اطراف تنگه ترکیبی از جنگل و مرتع است: بلوط، بادام کوهی، زالزالک و گیاهان دارویی و معطر مانند آویشن، گل گاوزبان و نعنا در دامنه‌ها و حاشیه رود می‌روید. همین پوشش گیاهی، زیست‌بومی برای حیات وحش ساخته است: بز کوهی، میش، روباه و خزندگانی مانند مار در منطقه دیده یا گزارش شده‌اند. در تابستان حشرات و پشه‌ها فعال‌تر هستند و گیاهان دارویی نباید بدون رعایت قاعده برداشت شوند؛ برداشت بی‌رویه، همان پوششی را از بین می‌برد که زیبایی و سایه تنگه به آن بسته است.</p>
<p>فاصله با حیات وحش قاعده ساده‌ای دارد: نزدیک نشوید، غذا ندهید و مسیر عبور جانوران را نبندید. مارها هم بخشی از منطقه‌اند؛ روی سنگ‌های گرم استراحت می‌کنند و پیش از نشستن یا برداشتن وسایل، اطراف را یک بار نگاه کنید.</p>

<h2>مناسب چه کسانی است؟</h2>
<ul>
<li><strong>طبیعت‌گردان و عکاسان:</strong> صخره‌های بلند، حوضچه‌های زلال و پوشش گیاهی متنوع، فرصت‌های عکاسی گسترده‌ای فراهم می‌کند.</li>
<li><strong>علاقه‌مندان به طبیعت و زمین‌شناسی:</strong> حوضچه‌ها، دیواره‌های فرسایشی و کتیبهٔ تاریخی را از مسیرهای مجاز تماشا کنید.</li>
<li><strong>طبیعت‌گردان با آمادگی مناسب:</strong> پیاده‌روی از روستا و عبور از بخش‌های ناهموار به کفش مناسب و ارزیابی توان گروه نیاز دارد؛ زمان مسیر ثابت نیست.</li>
<li><strong>علاقه‌مندان تاریخ و باستان‌شناسی:</strong> کتیبه یونانی تنگه، این مسیر را برایشان به یک مقصد مستند تبدیل می‌کند.</li>
</ul>
<p><strong>نامناسب برای:</strong> سالمندان، خانواده‌های دارای کودکان خردسال و افرادی که آمادگی جسمانی ندارند. مسیر پیاده‌روی در بخش‌هایی نیازمند عبور از صخره‌ها و آشنایی با اصول اولیه کوهنوردی است.</p>

<h2>نکات ایمنی و محیط‌زیستی</h2>
<ul>
<li><strong>عبور از صخره‌ها با احتیاط:</strong> داخل تنگه صخره‌هایی وجود دارد که عبور از آن‌ها آشنایی با اصول اولیه کوهنوردی و تجهیزات ساده می‌خواهد.</li>
<li><strong>ورود به آب:</strong> این راهنما شنا یا آب‌تنی را توصیه نمی‌کند؛ عمق و جریان تغییر می‌کند و سنگ‌های خیس لغزنده‌اند. اگر شرایط و مقررات همان روز روشن نیست، از حاشیهٔ آب فاصله بگیرید.</li>
<li><strong>کفش مناسب:</strong> مسیر کوهستانی و سنگ‌های خیس لغزنده‌اند؛ کفش کوهنوردی چنگ‌دار بپوشید.</li>
<li><strong>آب و خوراکی همراه ببرید:</strong> نزدیک تنگه امکاناتی برای تهیه غذا و آب نیست.</li>
<li><strong>بررسی شرایط جوی:</strong> با بارش باران، سطح صخره‌ها لغزنده و خطرناک می‌شود؛ وضعیت هوا را پیش از حرکت بررسی کنید.</li>
<li><strong>فاصله با حیات وحش:</strong> منطقه زیستگاه بز کوهی، میش، روباه و مار است؛ فاصله خود را حفظ کنید.</li>
<li><strong>زباله را با خود ببرید:</strong> منطقه فاقد سیستم جمع‌آوری زباله است؛ هرچه آورده‌اید بازگردانید.</li>
<li><strong>رعایت حریم کتیبه تاریخی:</strong> در صورت مشاهده کتیبه یونانی، از تماس فیزیکی با آن خودداری کنید و به آن آسیب نزنید.</li>
<li><strong>آنتن و زمان برگشت:</strong> در دره آنتن‌دهی کامل نیست؛ زمان بازگشت را با همراهان هماهنگ کنید و پیش از تاریکی از تنگه بیرون بیایید.</li>
</ul>

{{GALLERY:river}}

<h2>جدول شناسنامه و دسترسی تنگه لی لی (سورپیلو)</h2>
