<h2>فرهنگ بومی، محصولات روستای چمنار و خوراک محلی</h2>
<p>نام «لی‌لی» در زبان مردم بومی منطقه به گیلاس‌های وحشی و ریز کوهستانی اشاره دارد و باغ‌های روستاهای چمنار و سیره در بهار و تابستان سرشار از طراوت‌اند. اهالی خون‌گرم دهستان حشمت‌آباد به باغداری و دامداری مشغول‌اند؛ خرید گیلاس، گردو، بادام، عسل کوهستان و لبنیات محلی از روستاییان و صرف ناهار سنتی لری (کباب و زیربرنجی) در بازگشت به <a href="/city/dorud/">دورود</a>، لذت این گشت دره‌ای را کامل می‌کند.</p>

<h2>برنامه پیشنهادی بازدید و اقامت</h2>
<ol>
<li>زمان رانندگی تا چمنار را با مسیریاب و شرایط جادهٔ همان روز بسنجید و حرکت را طوری برنامه‌ریزی کنید که پیمایش در روشنایی انجام شود.</li>
<li>خودرو را در جای مطمئن روستا یا نزدیکی ورودی پارک کنید و از اهالی وضعیت مسیر و آب را بپرسید.</li>
<li>از روستا در مسیر مجاز به سمت تنگه پیاده بروید؛ زمان لازم به وضعیت پاکوب و توان گروه بستگی دارد.</li>
<li>دو تا سه ساعت برای بازدید از مسیرهای مجاز و تماشای حوضچه‌ها و دیواره‌ها در نظر بگیرید؛ وارد آب نشوید و روی سنگ‌های خیس با احتیاط حرکت کنید.</li>
<li>برای ناهار به روستا برگردید. وجود فروشگاه یا اقامتگاه را قطعی فرض نکنید و پیش از سفر خدمات فعال و امکان اقامت را از اهالی یا مرجع محلی بپرسید.</li>
<li>اگر روز دوم دارید، مسیر را با <a href="/attraction/aznadar-waterfall-doroud/">آبشار ازنادر</a> یا <a href="/attraction/babahur-forest-park-dorud/">پارک جنگلی باباهور</a> کامل کنید.</li>
</ol>

