<p>وقتی وارد <a href="/city/khorramabad/">خرم‌آباد</a> می‌شوید، نخستین تصویری که نگاهتان را بر فراز شهر می‌رباید، دیوارهای بلند آجری و هشت برج سترگ <strong>قلعه فلک‌الافلاک</strong> (<strong>دژ شاپورخواست</strong>) بر تپه‌ای صخره‌ای و باستانی است<sup class="sa-cite"><a href="https://www.visitiran.ir/fa/attraction/%D9%82%D9%84%D8%B9%D9%87-%D9%81%D9%84%DA%A9-%D8%A7%D9%84%D8%A7%D9%81%D9%84%D8%A7%DA%A9">۱</a></sup>. این شاهکار مهندسی و نظامی که هستهٔ نخستین آن در روزگار ساسانیان پی‌ریزی شده و در دوره‌های آل حسنویه، آل بویه، اتابکان لر کوچک، صفویه و قاجار بالیده است<sup class="sa-cite"><a href="https://www.iranicaonline.org/articles/korramabad">۲</a></sup>، امروز به عنوان نماد تاریخی <a href="/province/lorestan/">استان لرستان</a> و یکی از مهم‌ترین پرونده‌های در نوبت ثبت جهانی یونسکو شناخته می‌شود<sup class="sa-cite"><a href="https://whc.unesco.org/en/tentativelists/5209/">۳</a></sup>.</p>
<p>فلک‌الافلاک امروز فقط یک بنای دیدنی نیست؛ مجموعه‌ای زنده از موزه مردم‌شناسی و باستان‌شناسی لرستان، چای‌خانه سنتی و بازارچه صنایع دستی است که بازدید از آن هم درس تاریخ می‌دهد و هم چشم‌اندازی ۳۶۰ درجه از شهر و کوه‌های زاگرس هدیه می‌کند. برخلاف بسیاری از قلعه‌های تاریخی ایران که بیرون شهر مانده‌اند، اینجا وسط شهر است و مسیر رسیدن به آن بخش ساده سفر می‌شود.</p>
