<p><strong>قله دماوند</strong> با ارتفاع ۵٬۶۱۰ متر، بلندترین چکاد ایران و خاورمیانه و مرتفع‌ترین آتشفشان قارهٔ آسیا است<sup class="sa-cite"><a href="https://www.britannica.com/place/Mount-Damavand">۱</a></sup>؛ کوهی باشکوه و مخروطی که در بخش لاریجان <a href="/city/amol/">شهرستان آمل</a> در <a href="/province/mazandaran/">استان مازندران</a> و در قلب رشته‌کوه البرز قد برافراشته است. دماوند برای ایرانیان تنها یک عارضهٔ زمین‌شناختی نیست؛ نماد اسطوره‌ای پایداری و آزادی در شاهنامهٔ فردوسی و ادب فارسی است<sup class="sa-cite"><a href="https://www.iranicaonline.org/articles/damavand">۲</a></sup> و نخستین اثر طبیعی ایران به شمار می‌رود که در فهرست آثار ملی و فهرست موقت میراث جهانی یونسکو جای گرفته است<sup class="sa-cite"><a href="https://whc.unesco.org/en/tentativelists/5278/">۳</a></sup>.</p>
<p>صعود به «بام ایران» کوه‌پیمایی ساده‌ای نیست. ارتفاع بالای ۵۶۰۰ متر، باد شدید، تغییر ناگهانی هوا و خطر بیماری ارتفاع، دماوند را به مقصدی جدی برای کوهنوردان آماده و باتجربه تبدیل می‌کند. پیش از برنامه‌ریزی، مسیر، شرایط جوی، مقررات روز و وضعیت پناهگاه‌ها را از مراجع رسمی و راهنمایان باتجربه بررسی کنید.</p>
{{GALLERY:south}}

<h2>چرا قله دماوند دیدنیِ شاخص ایران است؟</h2>
<ul>
<li><strong>بلندترین قله ایران و خاورمیانه:</strong> ارتفاع ۵۶۱۰ متر بر پایه درگاه ملی آمار و پایگاه ملی داده‌های علوم زمین؛ بعضی منابع قدیمی‌تر ۵۶۷۱ متر را ذکر کرده‌اند که امروز نادرست دانسته می‌شود.</li>
<li><strong>یکی از برجسته‌ترین کوه‌های جهان:</strong> ارتفاع نسبی دماوند حدود ۴۶۶۱ تا ۴۶۶۷ متر است و آن را در رده دوازدهم کوه‌های برجسته و مستقل دنیا قرار می‌دهد؛ همین ارتفاع نسبی است که دماوند را از فاصله‌های دور قابل دیدن می‌کند.</li>
<li><strong>نماد ملی و فرهنگی:</strong> دماوند در فرهنگ ایران مظهر پایداری و استواری است و در شاهنامه فردوسی و ادبیات فارسی جایگاهی ویژه دارد.</li>
<li><strong>آتشفشان چینه‌ای خفته:</strong> دماوند آتشفشان چینه‌ای است؛ گاز و بخار گوگردی در نزدیکی دهانه گزارش می‌شود و دسترسی به آن تابع شرایط فنی و ایمنی مسیر است.</li>
<li><strong>پوشش گیاهی ویژه دامنه‌ها:</strong> گونه‌هایی مانند بومادران، پیرگیاه دماوندی، اسپرس کوهی و گون در دامنه‌ها می‌روید و اواسط اردیبهشت تا اواسط خرداد، دشت‌های لار پوشیده از خشخاش لار می‌شود.</li>
</ul>

<h2>شناسنامه سریع دماوند</h2>
<ul>
<li>ارتفاع: ۵۶۱۰ متر (بلندترین قله ایران و خاورمیانه) · ارتفاع نسبی: حدود ۴۶۶۷ متر</li>
<li>موقعیت: استان مازندران، بخش لاریجان شهرستان آمل، مرکز رشته‌کوه البرز، جنوب دریای خزر</li>
<li>فاصله‌ها: حدود ۶۹ کیلومتر شمال‌شرق <a href="/city/tehran-city/">تهران</a>، حدود ۶۲ کیلومتر جنوب‌غرب <a href="/city/amol/">آمل</a> و حدود ۲۶ کیلومتر شمال‌غرب <a href="/city/damavand/">شهر دماوند</a></li>
<li>نوع: آتشفشان چینه‌ای خفته با دهانه و تصعید گازهای گوگردی</li>
<li>کمپ‌های شناخته‌شده مسیر جنوبی: گوسفندسرا حدود ۳۰۰۰ متر و پناهگاه بارگاه سوم حدود ۴۲۰۰ تا ۴۲۵۰ متر</li>
<li>وضعیت حفاظتی: اثر طبیعی ملی و نخستین اثر طبیعی ایران در فهرست آثار ملی (۱۳۸۷)؛ تحت مدیریت سازمان حفاظت محیط زیست</li>
<li><strong>مقررات دسترسی:</strong> نیاز به مجوز یا هماهنگی را پیش از برنامه‌ریزی از مراجع رسمی جویا شوید.</li>
</ul>

<h2>مسیرهای صعود؛ چهار جبهه اصلی</h2>
<p>دماوند از چهار جبهه اصلی صعود می‌شود: جنوبی، شمالی، شمال‌شرقی و غربی. مسیر جنوبی ساده‌ترین و قدیمی‌ترین راه است و بیشتر کوهنوردان از همان بالا می‌روند.</p>
<h3>۱) جبهه جنوبی (پلور و رینه)</h3>
<p>برای دسترسی به این جبهه از جاده هراز وارد پلور و رینه می‌شوید. صعود از گوسفندسرا (حدود ۳۰۰۰ متر) آغاز می‌شود و تا پناهگاه بارگاه سوم (حدود ۴۲۰۰ متر) نزدیک چهار ساعت راه است؛ از بارگاه سوم تا قله هم حدود شش ساعت صعود در پیش دارید. این مسیر چند جان‌پناه و پناهگاه دارد و به همین دلیل شلوغ‌ترین راه دماوند است.</p>
<h3>۲) جبهه غربی (سد لار)</h3>
<p>از جاده هراز و پلور وارد جاده سد لار می‌شوید و صعود را از پارکینگ ورارو در ارتفاع تقریبی ۳۴۰۰ متری شروع می‌کنید. پناهگاه سیمرغ در حدود ارتفاع ۴۲۰۰ متری میانه این مسیر قرار دارد و جبهه غربی از مسیرهای نسبتاً دشوارتر دماوند به شمار می‌آید.</p>
<h3>۳) جبهه شمال‌شرقی (ناندل)</h3>
<p>دسترسی این جبهه از روستای ناندل در جاده هراز است؛ مسیری رایج برای کوهنوردان باتجربه‌تر با شیب تندتر و پناهگاه‌های کمتر. در جبهه شمالی هم پناهگاه اصلی حدود ارتفاع ۴۶۰۰ متری قرار دارد.</p>
<h3>۴) جبهه شمالی</h3>
<p>جبهه شمالی دماوند خنک‌تر، برف‌گیرتر و دورافتاده‌تر است و پناهگاه‌های کمتری دارد؛ مناسب کسانی که مسیرهای فنی‌تر و خلوت‌تر را می‌خواهند و تجربه صعود در برف و یخ دارند.</p>
{{GALLERY:west}}
<p><strong>هماهنگی پیش از صعود:</strong> مقررات ورود، ثبت برنامه و نیاز به مجوز ممکن است تغییر کند. پیش از حرکت، شرایط روز، مسیر و پناهگاه‌ها را از مراجع رسمی و باشگاه یا راهنمای معتبر جویا شوید؛ این متن جایگزین مجوز یا راهنمای فنی نیست.</p>

<h2>جدول مقایسهٔ چهار جبههٔ اصلی صعود به قله دماوند</h2>
<table>
<thead><tr><th>جبههٔ صعود</th><th>مبدأ دسترسی جاده‌ای</th><th>پناهگاه و جان‌پناه شاخص</th><th>درجه سختی فنی</th><th>ویژگی کلیدی مسیر</th></tr></thead>
<tbody>
<tr><td>جبههٔ جنوبی (کلاسیک)</td><td>جاده هراز ← پلور ← رینه ← گوسفندسرا (۳۰۰۰ متر)</td><td>پناهگاه بارگاه سوم (۴۲۰۰ متر)<sup class="sa-cite"><a href="https://msfi.ir/ArticleView/Index/51429">۴</a></sup></td><td>متوسط تا سنگین (غیرفنی در تابستان)</td><td>رایج‌ترین مسیر با بیشترین امکانات پناهگاهی؛ شیب پیوسته و تپه گوگردی در بخش پایانی</td></tr>
<tr><td>جبههٔ غربی</td><td>جاده هراز ← پلور ← جاده سد لار ← پارکینگ ورارو (۳۴۰۰ متر)</td><td>پناهگاه سیمرغ (۴۲۰۰ متر)</td><td>سنگین</td><td>مسیر خلوت‌تر با چشم‌انداز دریاچه لار و تیغه‌های سنگی در ارتفاع بالا</td></tr>
<tr><td>جبههٔ شمال‌شرقی</td><td>جاده هراز ← روستای ناندل</td><td>جان‌پناه تخت فریدون (۴۳۶۰ متر)</td><td>سنگین و طولانی</td><td>عبور از دشت چمن و یخچال عروسک‌ها؛ نیازمند توان هوازی بالا</td></tr>
<tr><td>جبههٔ شمالی</td><td>جاده هراز ← روستای ناندل ← سنگ بزرگ</td><td>جان‌پناه ۴۰۰۰ و جان‌پناه ۵۰۰۰ (فرانسوی‌ها)</td><td>فنی و بسیار سنگین</td><td>یخچال‌های پرشیب (دوبی‌سل و سیوله)، درگیری با سنگ و یخ؛ ویژهٔ کوهنوردان حرفه‌ای</td></tr>
</tbody>
</table>

<h2>بهترین زمان صعود</h2>
<p>بسیاری از برنامه‌های صعود در ماه‌های گرم‌تر سال انجام می‌شوند، اما این بازه تضمین‌کنندهٔ هوای ایمن نیست. وضعیت برف، باد، دید، مقررات و آمادگی گروه را پیش از هر صعود بررسی کنید.</p>
<ul>
<li><strong>خرداد:</strong> در برخی سال‌ها دامنه‌های پایین‌دست گل‌دارند و ممکن است در ارتفاعات هنوز برف باقی مانده باشد؛ شرایط سالانه و مسیر را بررسی کنید.</li>
<li><strong>تیر و مرداد:</strong> پایدارترین هوا و بیشترین تعداد کوهنورد؛ اگر دنبال روزهای خلوت‌تر هستید، ابتدای هفته را انتخاب کنید.</li>
<li><strong>شهریور:</strong> هوا گرم‌تر و برف‌ها آب شده است، اما احتمال تغییر ناگهانی هوا و بادهای عصرگاهی بالا می‌رود.</li>
<li><strong>فصل نامناسب:</strong> از اواخر پاییز تا اوایل بهار (آذر تا اسفند) باد، برف و کولاک صعود را بسیار خطرناک و تقریباً غیرممکن می‌کند.</li>
</ul>

<h2>برای چه کسانی مناسب است؟</h2>
<ul>
<li><strong>کوهنوردان با آمادگی جسمانی بالا:</strong> دماوند محل آماده‌سازی اولیه نیست؛ خطر بیماری ارتفاع برای افراد ناآماده بالاست.</li>
<li><strong>کوهنوردان دارای مدارک آموزشی:</strong> داشتن مدارک کارآموزی کوه‌پیمایی و برف و سنگ و گذراندن کارگاه‌های هواشناسی، پزشکی کوهستان و ناوبری توصیه می‌شود.</li>
<li><strong>طبیعت‌گردان در ارتفاعات پایین:</strong> دامنه‌های پایین‌دست و منطقه پلور و لاریجان برای طبیعت‌گردی، عکاسی و کمپ در ارتفاع پایین‌تر مناسب است.</li>
</ul>
<p><strong>نامناسب برای:</strong> افراد بدون آمادگی جسمانی، کسانی که تجربه حضور در ارتفاعات بالا ندارند و افراد دارای بیماری قلبی یا تنفسی؛ برنامه صعود را بدون توصیه پزشک و مربی باتجربه شروع نکنید.</p>

<h2>آتشفشان دماوند و دهانه گوگردی</h2>
<p>دماوند آتشفشانی چینه‌ای است که از لایه‌های گدازه و خاکستر شکل گرفته است. این آتشفشان فوران فعال ثبت‌شده ندارد، اما بخار و گازهای گوگردی در نزدیکی دهانه گزارش می‌شود. نزدیک‌شدن به دهانه یا میدان‌های برفی، برنامه‌ای فنی و پرخطر است؛ برای تماشا یا عکاسی از این محدوده، از مسیر عادی خارج نشوید و بدون راهنمای فنی اقدام نکنید.</p>
<p>قرار گرفتن در محدوده دهانه و مسیرهای نزدیک آن، بدون راهنمای فنی و ماسک مناسب توصیه نمی‌شود؛ بخار و گاز می‌تواند تنفس را سخت کند. همچنین با گرم‌شدن اقلیم، محدوده یخچال‌های دائمی دماوند حساس‌تر شده است؛ از ورود به محدوده یخچال‌ها و مسیرهای مجاور آنها خودداری کنید.</p>
{{GALLERY:crater}}

<h2>فرهنگ بومی، آبگرم‌های لاریجان و سوغات دامنه‌های دماوند</h2>
<p>سفر به دماوند تنها به قلهٔ ۵٬۶۱۰ متری خلاصه نمی‌شود؛ بخش لاریجان در <a href="/city/amol/">شهرستان آمل</a> و روستاهای تاریخی رینه، گزانه، ناندل و اسک، فرهنگی غنی از زندگی کوهستانی البرز را در خود جای داده‌اند. پس از یک صعود نفس‌گیر، استراحت در چشمه‌های آبگرم معدنی رینه و لاریجان (که از فعالیت گرمایی آتشفشان دماوند سرچشمه می‌گیرند) سنت دیرینهٔ کوهنوردان است.</p>
<ul>
<li><strong>خوراک‌های محلی رینه و لاریجان:</strong> <strong>آش دوغ داغ لاریجان</strong>، <strong>کباب و جگر در رینه</strong>، <strong>اکبرجوجه و کباب ترش مازندرانی</strong> در مسیر هراز و صبحانهٔ محلی با سرشیر، کره و عسل کوهستان.</li>
<li><strong>سوغات اصیل منطقه:</strong> <strong>عسل طبیعی گون و آویشن دامنه‌های دماوند و دشت لار</strong>، لبنیات سنتی لاریجان، گردو، آلبالو و گیلاس باغ‌های کوهپایه‌ای و گیاهان معطر کوهی.</li>
</ul>

<h2>نکات ایمنی پیش از صعود و راهنماهای آموزشی مکمل</h2>
<p>برای آمادگی کامل در برابر شرایط ارتفاع بالای ۴٬۰۰۰ متر، مطالعهٔ راهنماهای <a href="/outdoor-clothing-guide/">لایه‌بندی استاندارد لباس کوهستان</a>، <a href="/hypothermia-first-aid/">پیشگیری و درمان هیپوترمی</a>، <a href="/camping-essential-checklist/">تحلیل هواشناسی کوهستان</a>، <a href="/gps-navigation-tools/">ناوبری با GPS در مه و کولاک</a> و <a href="/how-to-choose-camping-tent/">انتخاب چادر مقاوم در برابر باد</a> در سرزمین آریان به شما کمک می‌کند صعودی ایمن‌تر داشته باشید.</p>
<ul>
<li><strong>هم‌هوایی تدریجی:</strong> فرآیند سازگاری با ارتفاع باید پیش از ورود به ارتفاع بالا و به‌تدریج انجام شود؛ روز دوم را به صعود تا ارتفاع بالاتر و بازگشت اختصاص دهید.</li>
<li><strong>هماهنگی صعود:</strong> نیاز به ثبت برنامه، مجوز، راهنما یا همراهی گروه را از مراجع رسمی و باشگاه معتبر بررسی کنید.</li>
<li><strong>تجهیزات:</strong> لباس گرم، بارانی و بادگیر، کفش کوهنوردی، کیسه‌خواب، چادر مقاوم به باد، عینک و کرم ضدآفتاب، و در فصل‌های خنک‌تر تجهیزات زمستانی.</li>
<li><strong>خودداری از ورود به یخچال‌ها:</strong> با افزایش دما، مسیرهای مجاور یخچال‌های دائمی ناایمن‌تر شده‌اند.</li>
<li><strong>برنامه بازگشت:</strong> زمان شروع و نقطه بازگشت را از قبل مشخص کنید؛ بیشتر حوادث دماوند در مسیر فرود و به‌دلیل خستگی و تغییر هوا رخ می‌دهد.</li>
</ul>

<h2>قواعد محیط‌زیستی دماوند</h2>
<ul>
<li><strong>رعایت مسیرهای مجاز:</strong> از مسیرهای تعیین‌شده خارج نشوید و ضوابط روز منطقه را رعایت کنید.</li>
<li><strong>مدیریت پسماند:</strong> زباله را با خود به پایین برگردانید و محل استراحت را پاکیزه ترک کنید.</li>
<li><strong>حفاظت از طبیعت:</strong> به پوشش گیاهی و حیات‌وحش آسیب نزنید و از چیدن گیاهان خودداری کنید.</li>
</ul>

<h2>برنامه پیشنهادی صعود</h2>
<ol>
<li><strong>روز اول:</strong> رسیدن به پلور یا رینه، بررسی وضعیت برنامه و انجام هماهنگی یا ثبت‌نامی که مرجع مسئول همان روز اعلام می‌کند؛ شب‌مانی و استراحت برای هم‌هوایی اولیه.</li>
<li><strong>روز دوم:</strong> صعود از گوسفندسرا به سمت پناهگاه بارگاه سوم (حدود ۴۲۰۰ متر) و شب‌مانی در پناهگاه یا جان‌پناه مسیر.</li>
<li><strong>روز سوم:</strong> شروع صعود در ساعات بامدادی به قله، توقف کوتاه در دهانه و بازگشت به بارگاه سوم یا فرود تا پایین؛ کوهنوردان آماده‌تر و باتجربه‌تر برنامه دو روزه هم می‌بندند.</li>
<li><strong>پس از صعود:</strong> یک روز اضافه برای بازگشت و استراحت در نظر بگیرید تا برنامه فشار مضاعف نشود.</li>
</ol>

<h2>عکاسی از دماوند</h2>
<p>در هوای صاف، دماوند از برخی نقاط پیرامونی مانند ارتفاعات پلور، پارک ملی لار، الیمستان و روستای لاسم دیده می‌شود. میزان دید، برف‌پوشی قله و شرایط عکاسی با فصل و وضعیت هوا تغییر می‌کند؛ برای عکاسی شبانه یا ورود به محدوده‌های طبیعی، مقررات و دسترسی روز را رعایت کنید.</p>

<h2>جاذبه‌های مرتبط</h2>
<ul>
<li><a href="/province/mazandaran/">استان مازندران</a> و <a href="/city/amol/">شهرستان آمل</a>؛ استان و شهرستان میزبان قله</li>
<li><a href="/province/tehran/">استان تهران</a> و <a href="/city/tehran-city/">تهران</a>؛ بهترین نقطه تماشای دماوند از فاصله دور</li>
<li>پارک ملی لار؛ منطقه حفاظت‌شده پشت کوه و مسیر جبهه غربی</li>
<li>دریاچه‌های تار و هویر؛ دو دریاچه کوهستانی حدود ارتفاع ۲۵۰۰ متری، در حدود ۳۰ کیلومتری شرق دماوند</li>
<li>آبشار جنگلک؛ آبشاری در شرق شهرستان دماوند، مناسب بهار و اوایل تابستان</li>
<li>غار رودافشان؛ غاری در حدود ۳۵ کیلومتری شهر دماوند</li>
<li>چشمه اعلا؛ چشمه شاخص منطقه دماوند که پاییز آن را به تابلوی رنگ و نور تبدیل می‌کند</li>
<li>دشت مشا؛ دشتی در دامنه‌های دماوند، مناسب طبیعت‌گردی و پیک‌نیک</li>
</ul>
