		'content'      => <<<'SA_ART'
<p>وقتی در دالان‌های باریک و میان ستون‌های سر به فلک کشیدهٔ <strong>درهٔ ستارگان</strong> در جنوب شرقی <a href="/city/qeshm/">جزیرهٔ قشم</a> قدم می‌زنید، حس می‌کنید روی سیاره‌ای دیگر ایستاده‌اید؛ جایی که بادهای موسمی خلیج فارس و رگبارهای تند فصلی، فلات رسوبی جزیره را در گذر هزاران سال تراشیده و تندیس‌هایی شگفت‌انگیز خلق کرده‌اند<sup class="sa-cite"><a href="https://qeshmgeopark.ir/geosites">۱</a></sup>. این پدیدهٔ منحصربه‌فرد در نزدیکی روستای نمونهٔ گردشگری برکه خلف، در <a href="/province/hormozgan/">استان هرمزگان</a> قرار دارد و با شناسهٔ رسمی G01 یکی از درخشان‌ترین ژئوسایت‌های <strong>ژئوپارک جهانی قشم</strong> در شبکهٔ ژئوپارک‌های یونسکو است<sup class="sa-cite"><a href="https://www.unesco.org/en/iggp/geoparks">۲</a></sup>.</p>
<p>آنچه اینجا می‌بینید نتیجهٔ اختلاف سختی دو لایه زمین است: لایهٔ زیرین نرم، کرم و خاکستری که آب و باد آن را کنده و لایهٔ بالایی سخت و سفید که مثل کلاه روی ستون‌ها باقی مانده است. طول دره چند صد متر است و پیمایش آرام آن با عکاسی حدود یک تا دو ساعت زمان می‌برد؛ ستون‌ها در بعضی نقاط تا حدود ۱۵ متر بالا آمده‌اند.</p>
{{GALLERY:stars}}

<h2>چرا درهٔ ستارگان دیدنیِ شاخص است؟</h2>
<h3>لایه‌های رسوبی و فرسایش در چشم‌انداز دره</h3>
<p>دیواره‌ها و ستون‌های فرسایشی، لایه‌های رسوبی و روند فرسایش را در بخشی از چشم‌انداز جزیره نشان می‌دهند؛ دره یکی از ژئوسایت‌های رسمی ژئوپارک جهانی قشم است.</p>
<h3>ستون‌ها و مخروط‌هایی با فرم فرازمینی</h3>
<p>شکل‌های فرسایشی دره، از دودکش‌های شنی و مخروط‌های نوک‌تیز تا دیواره‌های موج‌دار، در عکس‌ها گاه به سطح ماه یا مریخ تشبیه می‌شوند. برای عکاسی، از مسیرهای مجاز استفاده کنید و پیش از پرواز پهپاد، مجوزهای لازم را از ژئوپارک و مراجع محلی بگیرید.</p>
<h3>صدای دره و روایت‌های محلی</h3>
<p>دربارهٔ نام «درهٔ ستارگان» روایت محلی‌ای به صداهای شبانه و شکل‌های فرسایشی دره پیوند داده می‌شود. باد ممکن است در حفره‌ها صدا ایجاد کند، اما این روایت را باید افسانه یا برداشت محلی دانست، نه توضیح قطعیِ منشأ نام.</p>
<h3>جزء ژئوپارک جهانی قشم</h3>
<p>ژئوپارک جهانی قشم در فهرست رسمی یونسکو قرار دارد و درهٔ ستارگان یکی از ژئوسایت‌های معرفی‌شدهٔ آن است. دربارهٔ مرز ژئوسایت و مسیرهای بازدید، به نقشه و اطلاعیه‌های رسمی ژئوپارک رجوع کنید.</p>
<h3>دسترسی کوتاه از شهر قشم</h3>
<p>برخلاف بسیاری از جاذبه‌های دورافتاده جنوب، درهٔ ستارگان با حدود ۲۰ کیلومتر رانندگی از شهر قشم و با خودروی معمولی قابل دسترسی است؛ همین موضوع آن را به گزینه‌ای مناسب برای سفر یک‌روزه و سفرهای خانوادگی تبدیل می‌کند.</p>

<h2>شناسنامه سریع درهٔ ستارگان</h2>
<ul>
<li><strong>استان و شهرستان:</strong> هرمزگان، شهرستان قشم</li>
<li><strong>نزدیک‌ترین روستا:</strong> برکه خلف</li>
<li><strong>فاصله از شهر قشم:</strong> حدود ۲۰ کیلومتر (۱۵ تا ۲۲ کیلومتر بسته به مسیر)</li>
<li><strong>پدیدهٔ شاخص:</strong> دیواره‌ها و ستون‌های فرسایشی در لایه‌های رسوبی</li>
<li><strong>ارتفاع ستون‌ها:</strong> تا حدود ۱۵ متر</li>
<li><strong>جنس سنگ:</strong> ماسه، رسوب و سیمان آهکی در دو لایهٔ نرم و سخت</li>
<li><strong>سطح دسترسی:</strong> متوسط؛ جادهٔ آسفالته تا نزدیکی دره و مسیر شنی ناهموار در بستر آن</li>
<li><strong>مدت بازدید:</strong> ۱ تا ۲ ساعت</li>
</ul>

<h2>موقعیت و مسیر دسترسی</h2>
<p>دره در فاصلهٔ حدود ۲۰ کیلومتری شهر قشم و در نزدیکی روستای برکه خلف قرار دارد. مسیر معمول این است: از شهر قشم به سمت شرق و جنوب شرقی جزیره، بعد از حدود ۲۰ کیلومتر به سمت روستای برکه خلف بروید و پس از عبور از روستا، جادهٔ خاکی کوتاهی شما را به دهانهٔ دره و پارکینگ و باجهٔ ورود می‌رساند.</p>
<p>اگر از بندرعباس می‌آیید، با پل خلیج فارس (حدود دو کیلومتر) وارد جزیره قشم می‌شوید و از آنجا مسیر شهر قشم و برکه خلف را ادامه می‌دهید. تاکسی، تورهای یک‌روزه و رانندگان محلی هم این مسیر را پوشش می‌دهند و برای کسانی که خودرو ندارند گزینهٔ راحت‌تری هستند. نزدیک‌ترین امکانات اقامتی و رستوران در شهر قشم و روستاهای اطراف است و همراه داشتن آب به‌ویژه در فصل گرم ضروری است.</p>

<h2>بهترین زمان بازدید</h2>
<p>آبان تا فروردین بهترین بازهٔ بازدید است؛ دمای هوا در این ماه‌ها معتدل و آسمان جزیره شفاف‌تر است. بهمن و اسفند گزینهٔ خوبی برای ترکیب بازدید دره با پرنده‌نگری در تالاب‌های حرا و بازدید از دیگر ژئوسایت‌ها است.</p>
<p>از خرداد تا شهریور گرمای قشم بسیار شدید می‌شود و بازدید از دره بدون سایه می‌تواند خطرناک باشد؛ اگر در این فصل سفر می‌کنید، فقط ساعات ابتدای صبح یا نزدیک غروب را انتخاب کنید. بهترین ساعت روز در همه فصل‌ها، صبح زود و حوالی غروب است؛ هم نور بهتری برای عکس دارید و هم سنگ‌ها خنک‌ترند.</p>

<h2>مناسب چه کسانی است؟</h2>
<ul>
<li><strong>عکاسان و علاقه‌مندان زمین‌شناسی:</strong> فرم‌های فرسایشی و لایه‌بندی سنگ‌ها سوژهٔ اصلی این دره‌اند.</li>
<li><strong>خانواده‌ها:</strong> با نظارت کامل روی کودکان و پرهیز از بالا رفتن روی ستون‌ها، پیمایش مسیر اصلی برای خانواده‌ها ممکن است.</li>
<li><strong>ماجراجویان:</strong> بازدید شبانه، ترکیب دره با چاهکوه و غار نمکدان و کمپ‌های محلی گزینه‌های ماجراجویانه‌تری هستند.</li>
<li><strong>افراد با محدودیت حرکتی:</strong> بستر دره ناهموار است و پلهٔ استاندارد ندارد؛ این بازدید برای سالمندان کم‌تحرک و ویلچر مناسب نیست.</li>
</ul>

<h2>نکات ایمنی و محیط‌زیستی</h2>
<p>آب آشامیدنی، کلاه و کفش غیرلغزنده همراه ببرید و از بالا رفتن روی ستون‌ها و دیواره‌ها خودداری کنید؛ سنگ‌ها سست‌اند و ریزش می‌کنند. پس از باران، کف دره گلی و لغزنده می‌شود و در صورت اعلام بارش سنگین، احتمال جریان ناگهانی آب در بستر دره جدی است.</p>
<p>نوشتن یادگاری روی سنگ‌ها، شکستن و برداشتن سنگ و صدف، روشن‌کردن آتش و رهاکردن زباله ممنوع است؛ این دره یک اثر زمین‌شناسی ثبت‌شده در ژئوپارک است و آسیب به آن برگشت‌پذیر نیست. برای بازدید شبانه همراه راهنمای محلی بروید و صدای محیط را با بلندگو و موسیقی آلوده نکنید.</p>

<h2>برنامه پیشنهادی بازدید</h2>
<ol>
<li><strong>صبح:</strong> حرکت از شهر قشم یا بندرعباس به سمت برکه خلف و بازدید از درهٔ ستارگان در ساعات خنک صبح.</li>
<li><strong>میانه روز:</strong> دیدار از روستای برکه خلف و آشنایی با صنایع دستی و زندگی محلی، و استراحت در سایه یا رستوران‌های اطراف.</li>
<li><strong>بعدازظهر:</strong> ادامه مسیر به سمت تنگهٔ چاهکوه (حدود ۷۰ کیلومتر دورتر) یا بازگشت به شهر قشم برای بازدید از بندر و بازار.</li>
<li><strong>غروب:</strong> اگر شب را در جزیره می‌مانید، غروب سواحل جنوبی و بازدید شبانهٔ دره با راهنمای محلی را از دست ندهید.</li>
</ol>
{{GALLERY:columns}}

<h2>جدول شناسنامهٔ ژئوسایت درهٔ ستارگان و جاذبه‌های همجوار در قشم</h2>
<table>
<thead><tr><th>شاخص یا ژئوسایت</th><th>موقعیت و فاصله</th><th>ویژگی زمین‌شناختی و گردشگری</th><th>بهترین ساعت بازدید</th></tr></thead>
<tbody>
<tr><td>درهٔ ستارگان (استاره‌کفته)</td><td>۵ کیلومتری ساحل جنوبی قشم (مجاور روستای برکه خلف)</td><td>ستون‌ها، دالان‌ها و مخروط‌های فرسایشی ماسه‌سنگ و مارن از دورهٔ پلیستوسن</td><td>۲ ساعت پیش از غروب آفتاب یا صبح زود</td></tr>
<tr><td>روستای پاک برکه خلف</td><td>ورودی درهٔ ستارگان</td><td>تمیزترین روستای ایران با اقامتگاه‌های بوم‌گردی، صنایع دستی گلابتون‌دوزی و غذاهای دریایی</td><td>ظهر و عصر برای استراحت و ناهار محلی</td></tr>
<tr><td>جزایر ناز</td><td>حدود ۱۰ کیلومتری شرق درهٔ ستارگان</td><td>ساحل جزرومدی که در زمان جزر با پس‌روی آب دریا، پیاده‌روی تا صخره‌های جزیره ممکن می‌شود</td><td>بر اساس جدول روزانهٔ جزر و مد دریا</td></tr>
<tr><td>غارهای خربس</td><td>در مسیر شهر قشم به درهٔ ستارگان</td><td>دهلیزهای صخره‌ای کنده‌شده در دل تپه‌های مرجانی ساحل جنوبی</td><td>ابتدای صبح در مسیر حرکت از شهر قشم</td></tr>
</tbody>
</table>

<h2>فرهنگ بومی روستای برکه خلف، خوراک محلی و سوغات قشم</h2>
<p>نقطهٔ ورود به درهٔ ستارگان، <strong>روستای برکه خلف</strong> است؛ روستایی که به دلیل مشارکت مثال‌زدنی زنان و خانواده‌های بومی در پاکیزگی کوچه‌ها و حفظ محیط‌زیست، بارها به عنوان یکی از پاکیزه‌ترین روستاهای ایران شناخته شده است. مدیریت بومی ژئوسایت و بازارچهٔ صنایع دستی ورودی دره، نمونه‌ای موفق از ژئوتوریسم جامعه‌محور در جزیره قشم است.</p>
<ul>
<li><strong>غذاهای محلی قشم و برکه خلف:</strong> در اقامتگاه‌های بوم‌گردی برکه خلف و روستاهای سهیلی و طبل، حتماً طعم <strong>قلیه‌ماهی و قلیه‌میگو جنوبی</strong>، <strong>هواری ماهی و میگو</strong>، <strong>کوسه (پودینی)</strong>، <strong>کلمبا</strong>، <strong>زیبون</strong> و <strong>نان تمشی (مهیاوه و پنیر و تخم‌مرغ روی تابهٔ داغ)</strong> را امتحان کنید.</li>
<li><strong>صنایع دستی و سوغات جزیره:</strong> <strong>گلابتون‌دوزی</strong>، <strong>خوس‌دوزی</strong>، <strong>شک‌بافی و بادله‌دوزی</strong> (که زنان برکه خلف استادکار آن هستند)، عود و بخور سنتی، ادویه‌های ترکیبی جنوب و صنایع دستی دریایی.</li>
</ul>

<h2>عکاسی در درهٔ ستارگان</h2>
<p>بهترین نور، صبح زود و یک ساعت پیش از غروب است؛ در این ساعات سایه‌های بلند، حجم ستون‌ها و حفره‌ها را نشان می‌دهند. لنز واید برای نمای کلی دره و لنز متوسط برای جزئیات دیواره‌ها مناسب است و برای مقیاس انسانی بهتر است در قاب تصویر یک نفر ایستاده باشد.</p>
<p>در زمان طوفان گرد و خاک از تعویض لنز خودداری کنید و دوربین را در کیف بسته نگه دارید. فلاش در این دره نتیجهٔ خوبی نمی‌دهد؛ نور طبیعی و کنتراست لایه‌ها جذاب‌ترین حالت را می‌سازد. پرواز پهپاد در محدودهٔ ژئوپارک و حریم روستا نیازمند مجوز است و بدون هماهنگی انجام نشود.</p>
