<ul>
<li><a href="/city/qeshm/">قشم</a>؛ مرکز جزیره با فرودگاه، هتل، مرکز خرید و اسکلهٔ سفر به هرمز</li>
<li><a href="/province/hormozgan/">استان هرمزگان</a>؛ از جزیره‌ها و سواحل خلیج فارس تا کوه‌های مریخی چابهار مسیر جنوب</li>
<li><a href="/city/bandar-e-abbas/">بندرعباس</a>؛ نقطه ورود اصلی با پل خلیج فارس و فاصلهٔ کوتاه تا قشم</li>
<li><a href="/city/minab/">میناب</a>؛ در مسیر سواحل شرقی استان و قلعه‌های تاریخی و تالاب‌های حرا</li>
<li><a href="/city/bandar-lengeh/">لنگه</a>؛ شهر ساحلی غرب هرمزگان در مسیر بندرهای خلیج فارس</li>
<li><a href="/city/khamir/">خمیر</a>؛ شهرستان نزدیک جزیره قشم با جنگل‌های حرا و تالاب‌های ساحلی</li>
