<li><a href="/attraction/azgan-wetland-dorud/">تالاب ازگن (قارون)</a>؛ تالابی کوهستانی برای مقایسه با تالاب‌های ساحلی جنوب</li>
<li><a href="/attraction/shahdad-kaluts-lut-desert/">کلوت‌های شهداد</a>؛ زمین‌چهرهای فرسایشی کویر لوت برای مقایسه با کال‌های قشم</li>
<li><a href="/attraction/mount-damavand-guide/">قلهٔ دماوند</a>؛ بلندترین قلهٔ ایران، برای مقایسهٔ اقلیم کوهستان و کویر</li>
<li><a href="/attraction/fin-garden/">باغ فین کاشان</a>؛ نمونه‌ای دیگر از میراث ثبت‌شدهٔ ایران در فهرست یونسکو</li>
</ul>
