<li><a href="/attraction/gahar-lake-dorud/">دریاچه گهر</a>؛ دریاچهٔ کوهستانی دامنهٔ اشترانکوه در جنوب شرقی دورود.</li>
<li><a href="/attraction/nigah-valley-dorud/">دره نیگاه (دره نگار)</a>؛ مسیر کوهستانی در محدودهٔ حفاظت‌شدهٔ اشترانکوه که به برنامه‌ریزی و آمادگی نیاز دارد.</li>
<li><a href="/attraction/babahur-forest-park-dorud/">تفرجگاه باباهور (بام دورود)</a>؛ نقطه‌ای آسان و خانوادگی برای تماشای چشم‌انداز شبانهٔ شهر دورود.</li>
<li><a href="/attraction/tangeh-lili-gorge-doroud/">تنگه لی لی (سورپیلو)</a> و <a href="/attraction/azgan-wetland-dorud/">تالاب ازگن</a>؛ دو مقصد دیگر در همین شهرستان برای تکمیل برنامهٔ سفر.</li>
</ul>
