<p>در طول مسیر، آب چند شاخهٔ رودخانه‌ای به هم می‌پیوندد و بستر دره را شکل می‌دهد. دیواره‌های صخره‌ای، آبشارها و مسیرهای ناهموار از ویژگی‌های این چشم‌اندازند؛ پیمایش آن را باید با توجه به وضعیت آب، زمان روشنایی و توان گروه برنامه‌ریزی کرد.</p>
