<h2>چرا دره نیگاه دیدنیِ شاخص دورود است؟</h2>
<ul>
<li><strong>مسیر رودخانه‌ای و دیواره‌های صخره‌ای:</strong> آبراهه‌ها و دیواره‌های فرسایشی، چشم‌انداز اصلی دره را می‌سازند؛ وضعیت جریان آب در فصل‌های مختلف یکسان نیست.</li>
<li><strong>مسیر دورافتاده و کم‌امکانات:</strong> در برخی بخش‌ها امکانات و پوشش تلفن همراه محدود است؛ برنامه‌ریزی، نقشهٔ آفلاین و همراهی فرد آشنا با مسیر اهمیت دارد.</li>
<li><strong>حیات گیاهی و جانوری غنی:</strong> گیاهان خوراکی مانند ریواس و درختان میوه‌ای نظیر انجیر، گردو و بادام در طول دره فراوان‌اند و منطقه زیستگاه روباه، گراز، گربه وحشی، خرس، گرگ و پلنگ است.</li>
</ul>

<h2>دره نیگاه کجاست؟</h2>
<p>دره نیگاه در محدودهٔ <a href="/city/dorud/">شهرستان دورود</a> و در منطقهٔ حفاظت‌شدهٔ اشترانکوه قرار دارد. مسیر کلاسیک آن، از درهٔ سمت چپِ چشمهٔ زیر پنبه‌کار در مسیر دریاچه گهر آغاز می‌شود و حدود ۶ کیلومتر پایین‌تر از دریاچه، بستر رود به تدریج به یک تنگهٔ عمیق و پرآب تبدیل می‌شود؛ تنگه‌ای که کوهنوردان نامش را از همین دره گرفته‌اند. انتهای دره به روستای تی می‌رسد و روستاهای تپه تی و درب آستانه در همسایگی آن قرار دارند.</p>
<p>گزارش‌ها دربارهٔ طول نی‌گاه متفاوت‌اند، چون مبدأ و انتهای پیمایش را یکسان تعریف نمی‌کنند. زمان لازم نیز به مسیر انتخابی، وضعیت آب‌وهوا و رودخانه، توان گروه و توقف‌ها بستگی دارد؛ پیش از سفر نقطهٔ شروع، مسیر برگشت و زمان‌بندی را با راهنمای آشنا هماهنگ کنید و برنامه را طوری ببندید که بازگشت در روشنایی ممکن باشد.</p>
{{GALLERY:oshtoran}}

<h2>سه مسیر دسترسی</h2>
<h3>مسیر یکم: از شهر دورود</h3>
<p>ابتدا به شهر دورود در استان لرستان بروید و از میدان اصلی شهر (میدان رضا) با وسیلهٔ نقلیه به سمت امامزاده پیرعبدالله حرکت کنید؛ سپس مسیر را تا <strong>روستای تی</strong> ادامه بدهید. این مسیر برای رسیدن به انتهای شمالی دره و شروع پیمایش از آن سمت کاربرد دارد.</p>
<h3>مسیر دوم: از دریاچهٔ گهر</h3>
<p>این مسیر از درهٔ سمت چپِ چشمهٔ زیر پنبه‌کار و در امتداد سنگ‌چین‌ها پیش می‌رود. در برخی قسمت‌ها مسیر به رودخانه نزدیک می‌شود؛ اگر آب بالا، جریان تند یا عمق نامشخص است، عبور نکنید و به مسیر امن بازگردید. از طناب یا راهکار دست‌ساز برای عبور استفاده نکنید؛ انتهای مسیر به روستای تی می‌رسد.</p>
<h3>مسیر سوم: از چشمه خرم</h3>
<p>مسیر چشمهٔ خرم، گردنهٔ سلام‌گاه و درهٔ گردو در بعضی راهنماها به‌عنوان راه دسترسی ذکر شده است؛ جزئیات آن به شرایط روز و وضعیت پاکوب وابسته است. بدون نقشه، راهنمای محلی و اطلاع از وضعیت رودخانه وارد شاخه‌های فرعی نشوید.</p>

<h2>جدول مقایسهٔ مسیرهای دسترسی و پیمایش دره نیگاه دورود</h2>
<table>
<thead><tr><th>مسیر دسترسی</th><th>نقطهٔ شروع و پایان</th><th>نوع پیمایش</th><th>نکتهٔ کلیدی ایمنی</th></tr></thead>
<tbody>
<tr><td>مسیر شمالی (از روستای تی)</td><td>دورود ← امامزاده پیرعبدالله ← روستای تی ← دهانهٔ دره نیگاه</td><td>ورود از پایین‌دست دره در خلاف جهت جریان گهررود</td><td>هماهنگی با پاسگاه محیط‌بانی پیش از روستای تی و بازگشت پیش از تاریکی<sup class="sa-cite"><a href="https://koohbist.com/blog/neygah-valley/">۳</a></sup></td></tr>
<tr><td>مسیر بالادست (از مسیر دریاچه گهر)</td><td>درب آستانه / چشمه خیه ← چشمه زیر پنبه‌کار ← دره نیگاه ← روستای تی</td><td>پیمایش خطی و سنگین در امتداد سنگ‌چین‌ها و حاشیهٔ رود</td><td>پرهیز مطلق از زدن به آب در جریان تند؛ نیازمند راهنمای مجرب و برنامهٔ ۲ روزه</td></tr>
<tr><td>مسیر فرعی دره گردو</td><td>چشمه خرم ← گردنه سلام‌گاه ← دره گردو ← تلاقی با دره نیگاه</td><td>کوهنوردی و دره‌پیمایی نیمه‌سنگین</td><td>نیازمند <a href="/gps-navigation-tools/">نقشه آفلاین GPS</a>، <a href="/ankle-sprain-first-aid/">کفش کوهنوردی</a> و استعلام وضعیت آب</td></tr>
</tbody>
</table>
{{GALLERY:range}}

<h2>بهترین زمان بازدید</h2>
<ul>
<li><strong>بهار:</strong> طبیعت سرسبزتر است، اما باران و برفاب می‌تواند سطح و جریان آب را تغییر دهد؛ وضعیت روز را از مرجع محلی بپرسید و در آب بالا یا جریان تند عبور نکنید.</li>
<li><strong>تابستان:</strong> ساعات روشنایی بلندتر است، ولی هوا و جریان رودخانه همچنان متغیرند؛ برای شب‌مانی یا پیمایش طولانی، ضوابط منطقه و وضعیت همان روز را بررسی کنید.</li>
<li><strong>پاییز:</strong> کوتاه‌شدن روز و سرمای شب را در زمان‌بندی در نظر بگیرید و برنامه را به روشنایی روز محدود کنید.</li>
<li><strong>زمستان:</strong> سرما، برف و یخ‌زدگی می‌تواند دسترسی را دشوار کند؛ پیش از هر برنامه از پاسگاه و راهنمای محلی استعلام کنید و در شرایط نامساعد سفر را لغو کنید.</li>
</ul>

<h2>این مسیر برای چه کسانی مناسب است؟</h2>
<ul>
<li><strong>کوهنوردان و طبیعت‌گردان باتجربه:</strong> پیمایش طولانی و مسیر‌یابی در محدودهٔ حفاظت‌شده به آمادگی، نقشه و شناخت شرایط رودخانه نیاز دارد؛ زمان ثابتی برای همهٔ گروه‌ها نمی‌توان تعیین کرد.</li>
<li><strong>گروه‌های همراه با راهنمای محلی:</strong> راهنما می‌تواند در انتخاب مسیر مجاز و ارزیابی شرایط کمک کند؛ او نیز نمی‌تواند عبور از آبِ نامطمئن را ایمن کند.</li>
<li><strong>برنامه‌های چندروزه:</strong> اگر قصد ترکیب نیگاه با دریاچهٔ گهر را دارید، زمان، مسیرهای دسترسی و مجوزهای هر بخش را جداگانه و با حاشیهٔ زمانی کافی برنامه‌ریزی کنید.</li>
<li><strong>خانواده‌ها و افراد کم‌تجربه:</strong> مسیر دورافتاده، نبود خدمات و محدودیت آنتن، بازدید خودسرانه را نامناسب می‌کند؛ سطح توان گروه را با راهنمای محلی بسنجید.</li>
</ul>

<h2>نکات ایمنی و محیط‌زیستی</h2>
<ul>
<li>پیش از سفر، از پاسگاه‌های محیط زیستِ مستقر پیش از روستای تی یا پاسگاه محیط زیست درب آستانه در ابتدای مسیر دریاچه گهر، دربارهٔ شرایط آب‌وهوایی و وضعیت مسیر اطلاعات بگیرید.</li>
<li>تنها از مسیرهای پاکوب‌شده و سنگ‌چین‌های مسیر حرکت کنید و وارد دره‌های فرعی و خطرناک نشوید.</li>
<li>در فصل‌های پرآب یا هنگام نامشخص‌بودن عمق و جریان، از عبور رودخانه خودداری کنید و به مسیر امن بازگردید؛ طناب یا ابزار دست‌ساز راه‌حل ایمن محسوب نمی‌شود.</li>
<li>منطقه خارج از پوشش تلفن همراه است و امکانات رفاهی ندارد؛ برنامهٔ سفر را پیش از حرکت با دیگران در میان بگذارید.</li>
<li>دره در زیستگاه خرس، گرگ و پلنگ است؛ خوراکی را در ظروف دربسته نگه دارید، شب‌مانی را با فاصله از بستر رود انجام بدهید و پسماند را نسوزانید.</li>
<li>چیدن گیاهان و شکستن شاخه‌ها ممنوع است و همهٔ زباله‌ها باید با شما از دره خارج شود.</li>
</ul>

<h2>برنامه‌ریزی بازدید</h2>
<ul>
<li>پیش از سفر، از پاسگاه محیط‌زیست و راهنمای محلی دربارهٔ مسیرهای باز، پیش‌بینی هوا، برفاب و وضعیت رودخانه سؤال کنید.</li>
<li>نقطهٔ شروع و خروج، وسیلهٔ برگشت و زمان لازم را بر اساس مسیر انتخابی و توان گروه مشخص کنید؛ برای همهٔ مسیرها یک زمان‌بندی ثابت وجود ندارد.</li>
<li>در طول پیمایش فقط در مسیر مجاز بمانید. اگر جریان رود تند، آب بالا یا عمق نامعلوم است، وارد آب نشوید و به نقطهٔ امن بازگردید.</li>
<li>زمان برگشت را طوری تنظیم کنید که پیش از تاریکی به محل خروج برسید؛ شب‌مانی را تنها پس از استعلام مجازبودن و هماهنگی با مرجع محلی در نظر بگیرید.</li>
</ul>

<h2>پیشنهاد عکاسی</h2>
<ul>
<li><strong>برش‌های صخره‌ای:</strong> با لنز واید از داخل بستر رود به سمت بالا، برای نمایش ارتفاع دیواره‌ها؛ مراقب پاشش آب روی لنز باشید.</li>
<li><strong>چشم‌انداز رود و دیواره‌ها:</strong> برای عکاسی از نقاط ثابت و امن استفاده کنید و به لبه‌ها یا بستر آب نزدیک نشوید.</li>
<li><strong>سرعت شاتر و ابریشمِ آب:</strong> با فیلتر ND و نوردهی طولانی، جریان رود را در میان صخره‌ها ابریشمی ثبت کنید؛ سه‌پایه ضروری است.</li>
<li><strong>نور داخل تنگه:</strong> نور مستقیم معمولاً در میانهٔ روز به بستر می‌رسد؛ برای دیواره‌های مرطوب و بازتاب‌ها همان ساعت‌ها بهترین نتیجه را می‌دهد.</li>
<li><strong>رنگ‌های پاییزی:</strong> ترکیب برگ‌های زرد انجیر و گردو با صخرهٔ خاکستری، قاب‌های مهر و آبانِ این دره را می‌سازد.</li>
</ul>
{{GALLERY:plain}}

<h2>مقصدهای مکمل سفر</h2>
<ul>
<li><a href="/attraction/gahar-lake-dorud/">دریاچهٔ گهر</a>؛ پهنهٔ کوهستانی در منطقهٔ حفاظت‌شدهٔ اشترانکوه.</li>
<li><a href="/attraction/bisheh-waterfall-dorud/">آبشار بیشه</a>؛ دسترسی آسان‌تر و مناسب برنامه‌های کوتاه‌تر در همین شهرستان.</li>
<li><a href="/attraction/tangeh-lili-gorge-doroud/">تنگهٔ لی‌لی (سورپیلو)</a>؛ دره‌ای صخره‌ای در محدودهٔ دورود با شرایط دسترسی متفاوت از نی‌گاه.</li>
<li><a href="/attraction/shevi-waterfall-tele-zang/">آبشار شوی (تله‌زنگ)</a>؛ آبشاری در خوزستان با مسیر ریلیِ شناخته‌شده از ایستگاه تله‌زنگ.</li>
<li><a href="/attraction/dorud-city/">شهرستان دورود</a>؛ راهنمای خودِ شهر و مقصدهای نزدیکِ همین خوشهٔ سفر.</li>
<li><a href="/attraction/babahur-forest-park-dorud/">تفرجگاه باباهور (بام دورود)</a> و <a href="/attraction/azgan-wetland-dorud/">تالاب ازگن</a>؛ دو مقصد آسان‌تر برای روزهای استراحتِ برنامهٔ لرستان.</li>
</ul>
