			array( 'q' => 'مهم‌ترین ویژگی معماری مقبره شاه قاسم انوار چیست؟', 'a' => 'ایوان رفیع به سبک معماری تیموری، گنبدخانهٔ چهارطاقی، حجره‌های دوطبقهٔ خانقاهی، گچ‌بری‌های ظریف و آب‌انبار و مسجدی که در مجموعهٔ باغ قرار دارند.' ),
