<tr><td>دورهٔ تاریخی و بانی</td><td>قرن نهم هجری (دورهٔ تیموری)؛ به دستور امیر علی‌شیر نوایی بر مزار شاه قاسم انوار (درگذشتهٔ ۸۳۷ ق)</td></tr>
