<tr><td>چشمه‌ها و ارتفاعات</td><td>بیش از ۲۰ چشمهٔ دائمی و فصلی (چشمه تنگ صیاد، صادق، سلطان‌ابراهیم) و قلهٔ ۳٬۱۵۰ متری جِهید</td></tr>
