<p>در شهری که اقلیمش بیابانی است و واژهٔ «کویری‌ترین شهر ایران» را با خود دارد، حوض آبی با سه فواره و ردیف درختان نارنج و خرما تصویر غریبی است. <strong>باغ گلشن</strong> در <a href="/city/tabas/">شهرستان طبس</a> و در <a href="/province/south-khorasan/">استان خراسان جنوبی</a> همین غرابت است: باغی ایرانی با پلانی تقریباً مربع که از اواخر دورهٔ زندیه به جا مانده و آبش از پیوستن چند رشته قنات اطراف شهر می‌آید.</p>

<h2>باغ گلشن چگونه ساخته شد؟</h2>
<p>منابع، ساخت باغ را به <strong>امیر محمدحسن خان عرب زنگویی</strong> معروف به میرحسن خان — از خان‌های منصوبِ دورهٔ نادری که بر تون (فردوس) و طبس حکومت می‌کرد — نسبت می‌دهند و زمانش را اواخر حکومت لطفعلی‌خان زند و آغاز قدرت‌گیری آقامحمدخان قاجار می‌دانند. سال دقیق ساخت روشن نیست؛ آن‌چه تاریخ‌دار است دو وقف‌نامه است: <strong>وقف اول در ۱۲۱۸ قمری</strong> که باغ و املاک زیادی را در بر می‌گیرد و <strong>وقف دوم در ۱۲۳۴ قمری</strong>. روی حلقهٔ درِ ورودی هم عبارتی با تاریخ ۱۳۳۸ قمری دیده می‌شود که به تعمیراتِ دوره‌های بعد اشاره دارد.</p>

<h2>معماری و پلانِ باغ</h2>
<ul>
<li><strong>پلان مربع:</strong> طول حدود <strong>۲۶۶ متر</strong>، عرض حدود <strong>۲۶۰ متر</strong> و مساحتی نزدیک به <strong>هفت هکتار</strong> (۷۴٬۴۳۸ متر مربع در یک منبع). مربع‌بودن، این باغ را از بسیاری باغ‌های ایرانی جدا می‌کند.</li>
<li><strong>الگوی چهارباغ:</strong> دو خیابان اصلی متقاطع، محوطه را به چهار مربع بزرگ تقسیم می‌کند و هر مربع با گذرگاه‌های کوچک به کرت‌های کشت می‌رسد.</li>
<li><strong>آبِ زنده:</strong> حوض میانی با سه فواره؛ آب پس از آبیاری کرت‌ها از زیر هشتیِ ساختمان سردر می‌گذرد و به شهر می‌رود. در منابع، استفاده از چاه آرتزین نیز به‌عنوان بخشی از سامانهٔ آبیاری ذکر شده است.</li>
<li><strong>عمارت سردر:</strong> تنها ساختمان باغ؛ عمارتی دوطبقه با زیرزمین کوچک، ایوانِ دوستونه، اندودِ گچ سفید و تزیینات آجری. ساختمان اصلی در زلزلهٔ سال ۱۳۵۷ آسیب دید و بعدها بر پایهٔ نقشهٔ پیشین بازسازی شد.</li>
<li><strong>گیاهان و پرندگان:</strong> درختان خرما در میان کرت‌ها، نارنج و انار و درختان کهن؛ و پلیکان‌هایی که پس از زلزله به باغ منتقل شدند و امروز بخشی از هویت باغ شده‌اند.</li>
<li><strong>موزهٔ زمین‌شناسی:</strong> در بخشی از باغ، مجموعه‌ای از کانی‌ها، سنگ‌ها و فسیل‌ها در «موزهٔ میراث زمین» نگه‌داری می‌شود.</li>
</ul>

<h2>اطلاعات بازدید</h2>
<p>آدرس باغ در شهر طبس و محور بلوار امام خمینی (ره) است. فاصله تا <a href="/attraction/tabas-attractions/">دیگر دیدنی‌های شهر</a> — مانند ارگ کهن و بافت قدیم — کوتاه است و می‌توان آن‌ها را در یک برنامه گنجاند. ساعات بازدید و تعرفهٔ باغ و موزه ممکن است متفاوت باشد و تغییر کند؛ پیش از رفتن، برنامهٔ روز و هزینه را از مرجع رسمی یا نگهبانیِ مجموعه بپرسید.</p>

<h2>تناسب بازدید برای خانواده‌ها، سالمندان و کودکان</h2>
<p>باغ گلشن طبس به دلیل قرارگیری در بافت مسطح شهری، داشتن مسیرهای عریض سنگ‌فرش‌شده، نیمکت‌های متعدد در سایهٔ درختان کهنسال و دسترسی نزدیک به سرویس‌های بهداشتی و پارکینگ در میدان گلشن، یکی از مناسب‌ترین جاذبه‌های خراسان جنوبی برای خانواده‌های دارای کودک، سالمندان و افراد کم‌توان حرکتی است. تنها بخش دارای پله، طبقهٔ بالای عمارت سردر است، در حالی که تمام محوطهٔ چهارباغ، کنار حوض بزرگ سه‌فواره و مسیرهای پیاده‌روی در تراز هم‌سطح و با شیب بسیار ملایم قابل پیمایش است.</p>

