<h2>مهندسی آب و راز سرسبزی باغ گلشن در دل کویر</h2>
<p>یکی از پرسش‌های همیشگی بازدیدکنندگان این است که چگونه باغی به وسعت هفت هکتار در یکی از گرم‌ترین و خشک‌ترین شهرهای حاشیهٔ کویر مرکزی ایران، قرن‌ها سرسبز و خرم مانده است؟ پاسخ در نبوغ مهندسی قنات و طراحی دقیق شیب زمین نهفته است. آب باغ گلشن از چشمه و قنات پرآب «سردر» (در امتداد مسیر چشمهٔ علی و کال سردر در کوهستان شتری) تأمین می‌شود. آب از ضلع شرقی وارد باغ شده، ابتدا حوض بزرگ مرکزی با ابعاد حدود ۶۷ در ۵۰ متر را پر می‌کند و به واسطهٔ اختلاف ارتفاع طبیعی، از سه فوارهٔ سنگی بدون نیاز به پمپ به هوا می‌جهد.</p>
<p>سپس جریان آب در جوی‌های منظمِ دو خیابان متقاطع و گذرگاه‌های فرعی میان چهار کرت بزرگ تقسیم می‌شود تا پای درختان نخل، نارنج، انار، سرو و گل‌های رز و ختمی را سیراب کند. نکتهٔ جالب در طراحی این باغ ایرانی آن است که درختان سایه‌انداز و بلند (مانند نخل خرما و چنار) در لایهٔ بالایی و درختان حساس‌تر به تابش مستقیم و تبخیر (مانند نارنج، پرتقال و انار) در سایهٔ خنک نخل‌ها کاشته شده‌اند؛ الگویی چندطبقه که رطوبت نسبی هوا را در درون دیوارهای باغ حفظ و دمای محیط داخلی را چندین درجه خنک‌تر از خیابان‌های اطراف می‌کند.</p>

<h2>سرگذشت باغ در زلزلهٔ ۱۳۵۷ و احیای دوبارهٔ عمارت سردر</h2>
<p>در شامگاه ۲۵ شهریور ۱۳۵۷، زلزلهٔ مهیب طبس بخش بزرگی از بافت خشتی شهر و عمارت تاریخی سردر باغ گلشن را ویران کرد، اما درختان استوار باغ و شبکهٔ آب‌رسانی آن زنده ماندند و در روزهای نخست پس از حادثه به پناهگاهی برای مردم تبدیل شدند. در سال‌های بعد، عمارت سردر دوطبقه با ایوان ستون‌دار و تزیینات گچ‌بری و آجرکاری، دقیقاً بر اساس نقشه‌ها و عکس‌های مستند پیش از زلزله بازسازی شد و پلیکان‌های سفید اهدایی به حوض بزرگ باغ، به نمادی از تداوم زندگی و امید در طبس بدل گشتند.</p>

<h2>راهنمای عکاسی و مسیر پیشنهادی قدم‌زدن در باغ</h2>
<p>برای ثبت بهترین عکس‌ها در باغ گلشن، بلافاصله پس از ورود از زیر هشتی عمارت سردر، در محور غربی حوض بزرگ بایستید؛ در این نقطه، تصویر متقارن عمارت سفیدرنگ سردر، سه فوارهٔ آب و ردیف نخل‌های سر به فلک کشیده در سطح آرام حوض منعکس می‌شود. سپس در خیابان اصلی شمالی–جنوبی قدم بزنید، از موزهٔ زمین‌شناسی (میراث زمین) دیدن کنید و در سایهٔ کرت‌های نارنج، بازی نور و سایهٔ برگ‌های نخل را بر جوی‌های آب به تصویر بکشید.</p>

<h2>فرهنگ باغ‌سازی کویری، عطر بهارنارنج و سوغات طبس</h2>
<p>در اواخر اسفند و نیمهٔ اول فروردین، وقتی هزاران درخت نارنج و پرتقال در زیر سایهٔ نخل‌های بلند باغ گلشن شکوفه می‌دهند، عطر بهارنارنج تمام فضای باغ و خیابان‌های اطراف را پر می‌کند؛ همان شکوفه‌هایی که زنان هنرمند طبسی از آن <strong>مربای بهارنارنج</strong>، <strong>عرق بهارنارنج</strong> و <strong>مربای بالنگ</strong> معروف طبس را می‌پزند. جهانگردان سرشناسی همچون <em>سون هدین</em> و <em>آندره گدار</em> در سفرنامه‌های خود از صدای فواره‌ها و سرسبزی شگفت‌انگیز این باغ در قلب کویر به نیکی یاد کرده‌اند.</p>
<ul>
<li><strong>سوغات و طعم‌های اطراف باغ:</strong> پس از گشت در باغ گلشن، در فروشگاه‌های محلی طبس حتماً <strong>مربای بهارنارنج</strong>، <strong>قطاب طبسی</strong>، <strong>خرمای مضافتی و کبکاب طبس</strong> و <strong>روغنی (نان شیرینی محلی)</strong> را تهیه کنید و برای ناهار، <strong>خورشت نخود طبسی</strong> یا <strong>آش جوش‌پره</strong> را امتحان نمایید.</li>
</ul>

<h2>بهترین زمان، نکات بازدید و مقصدهای مکمل</h2>
<ul>
<li><strong>فصل طلایی:</strong> اسفند و فروردین (فصل شکوفهٔ بهارنارنج و پرآب‌ترین حالت باغ) و مهر تا آذر (هوای خنک پاییزی).</li>
<li><strong>ساعت طلایی عکاسی:</strong> یک ساعت پس از طلوع آفتاب یا یک ساعت پیش از غروب، زمانی که تصویر عمارت سردر سفیدرنگ و نخل‌ها در حوض بزرگ مرکزی منعکس می‌شود.</li>
