<h2>کجاست و چه نامی دارد؟</h2>
<p>قلعه در غرب بشرویه بر کوهی با ارتفاع حدود <strong>۴۰۰ متر از سطح زمین</strong> (و در منابع، ۱٬۲۵۰ متر از سطح دریا) قرار دارد. منابع فاصلهٔ آن از شهر را متفاوت نوشته‌اند — ۱۰، ۱۲ و ۱۴ کیلومتر — و موقعیتش را ۶ کیلومتری شمال شرقی روستای <strong>رقه</strong> ثبت کرده‌اند؛ همین نام باعث شده در بعضی منابع «قلعه دختر رقه» خوانده شود. کنار مسیر، آسیاب آبیِ کهنی به نام «آسیاب دهنه» هم هست که نشان می‌دهد این پهنه در گذشته مسیر آب و کشت بوده است.</p>

<h2>روایت‌های قدمت</h2>
<p>دربارهٔ زمان ساخت قلعه، منابع یک حرف نمی‌زنند و همین، بخشی از جذابیت آن است:</p>
<ul>
<li><strong>روایت ساسانی:</strong> مصالح و ملات (سنگ، گچ و آهک)، شکل پی‌سازی و پوشش اتاق‌ها، قلعه را در خانوادهٔ قلعه‌های «دختر»یِ بازمانده از دورهٔ ساسانی می‌نشاند؛ خانواده‌ای که نمونه‌هایش را در فیروزآباد، بجستان و شوشتر هم می‌بینیم. در یک مصاحبهٔ مسئول میراث فرهنگی شهرستان، قدمت بنا در حدود <strong>۱٬۵۰۰ تا ۲٬۰۰۰ سال</strong> و مربوط به پیش از اسلام دانسته شده است.</li>
<li><strong>روایت اسماعیلی:</strong> گروهی از منابع، ساخت یا دست‌کم استفادهٔ مجدد از قلعه را به فداییان اسماعیلی در دورهٔ سلجوقی نسبت می‌دهند؛ فرقه‌ای که در ناحیهٔ تون و طبس پناهگاه‌هایی داشت و جادهٔ ارتباطی تون به طبس از کنار همین محل می‌گذشت.</li>
<li><strong>لایهٔ متأخر:</strong> برخی نوشته‌ها از کاربرد قلعه تا دورهٔ افشاریه و زمان نادرشاه هم یاد می‌کنند و آن را نیازمند پژوهش بیشتر می‌دانند.</li>
</ul>
<p>پس آن‌چه مسلم است، این است که قلعه لایه‌های زمانی مختلفی را دیده و یافته‌های باستان‌شناسی، زندگی پیش از اسلام در آن را تقویت می‌کند.</p>

<h2>در قلعه چه می‌بینیم؟</h2>
<ul>
<li><strong>دیوارهای خشک‌چین در چهار سطح:</strong> به‌واسطهٔ ملات مقاوم، دیواره‌ها در چند ترازِ پشت‌سرهم بالا می‌روند و به فضای مرکزی قلعه می‌رسند.</li>
<li><strong>برج‌های دیده‌بانی:</strong> برج‌های مدور با ارتفاع تقریبی ۳ تا ۴ متر و دیوارهای به‌هم‌پیوسته که میدان دید چهارسویه می‌ساخته‌اند.</li>
<li><strong>دالان‌ها و تالارها:</strong> دالان‌های عریض و مسقف، اتاق‌های وسیع و اتاق شاه‌نشین.</li>
<li><strong>آب‌انبارها و انبار آذوقه:</strong> در منابع از چهار آب‌انبار در قلعه یاد شده که تنها یکی سالم مانده و پوشش گنبدیِ میانی‌اش از بین رفته است؛ فضای ذخیرهٔ آذوقه هم برای محاصره طراحی شده بود.</li>
</ul>

<h2>مسیر دسترسی و نکات بازدید</h2>
<p>از شهر بشرویه به سمت غرب و روستای رقه حرکت کنید؛ مسیر خودرو تا نزدیکی دامنه پیش می‌رود و بخش پایانی صعود پیاده است. صعود ساده نیست: <strong>سه ضلع قلعه پرتگاه است و تنها راه از سمت جنوب</strong> می‌گذرد، پس تنها نروید، کفش کوهستان بپوشید و در روزهای بارانی یا بادی شدید بالا نروید. از راه رفتن روی دیوارها و طاق‌های نیم‌فروریخته خودداری کنید؛ این بنا تاریخی است، نه مسیر کوه‌نوردی. برنامه را طوری بچینید که پیش از تاریکی به پایین برگردید و آب همراه داشته باشید.</p>

<h2>پیوند قلعه دختر با آسیاب دهنه، پل ترناو و شبکهٔ آب‌رسانی باستانی رقه</h2>
<p>بازدید از قلعه دختر بشرویه زمانی معنا و عمق کامل خود را نشان می‌دهد که آن را در کنار سازه‌های آبی تاریخیِ پای کوه ببینید. در دامنهٔ کوه قلعه دختر و در مسیر رودخانه و قنات، بقایای <strong>آسیاب آبی دهنه</strong> و <strong>بند و پل تاریخی ترناو</strong> قرار دارد؛ مجموعه‌ای مهندسی که نشان می‌دهد این تنگهٔ کوهستانی، گلوگاه حیاتی تقسیم آب به سمت دشت و روستای کهن رقه بوده است. در واقع، دژبانان قلعه دختر بر فراز قلهٔ ۴۰۰ متری، نه‌تنها راه کاروان‌روِ تون به طبس را دیده‌بانی می‌کردند، بلکه کنترل شریان آب شیرین منطقه را نیز در دست داشتند تا در روزگار ناامنی، آبادی‌های پایین‌دست و کاروان‌ها در امان بمانند.</p>

<h2>جدول شناسنامهٔ معماری و راهنمای صعود به قلعه دختر بشرویه</h2>
<table>
<thead><tr><th>شاخص</th><th>اطلاعات تاریخی و میدانی</th></tr></thead>
<tbody>
<tr><td>موقعیت و ارتفاع</td><td>غرب <a href="/city/boshruyeh/">بشرویه</a> (۶ کیلومتری شمال شرقی روستای رقه)؛ ارتفاع حدود ۴۰۰ متر از سطح دشت و ۱٬۲۵۰ متر از سطح دریا<sup class="sa-cite"><a href="https://borna.news/fa/news/1450580/">۱</a></sup></td></tr>
<tr><td>لایه‌های تاریخی</td><td>بنیان احتمالی ساسانی (پیش از اسلام)<sup class="sa-cite"><a href="https://www.iranicaonline.org/articles/qala-ye-doktar">۲</a></sup>، بازسازی و استفادهٔ نظامی در دورهٔ اسماعیلیان (سلجوقی) و بهره‌برداری تا عصر افشاریه</td></tr>
<tr><td>عناصر معماری دژ</td><td>حصار خشک‌چین در ۴ تراز، برج‌های مدور دیده‌بانی، دالان‌های مسقف، شاه‌نشین، انبار غلات و ۴ آب‌انبار ساروجی<sup class="sa-cite"><a href="https://www.isna.ir/news/1402010300825/">۳</a></sup></td></tr>
<tr><td>مسیر صعود</td><td>تنها یال قابل صعود از جبههٔ جنوبی کوه است (سه جبههٔ دیگر پرتگاه صخره‌ای تند دارد)</td></tr>
<tr><td>جاذبه‌های پایین‌دست</td><td>آسیاب آبی تاریخی دهنه، بند و پل ترناو و روستای کهن رقه</td></tr>
</tbody>
</table>

<h2>چرا قلعه دختر بشرویه شاهکار معماری نظامی کوهستان است؟</h2>
<p>هنگامی که از پایین‌دست دشت رقه به قلهٔ مخروطی کوه قلعه دختر نگاه می‌کنید، نخستین نکته‌ای که تحسین هر بیننده‌ای را برمی‌انگیزد، هم‌رنگی و پیوند بی‌نقص دیوارهای دژ با صخره‌های طبیعی کوه است. معماران باستانی این قلعه، به جای تسطیح کامل قله، دیوارها و برج‌ها را بر روی خطوط تراز طبیعی صخره و در <strong>چهار سطح پلکانی</strong> بنا کرده‌اند:</p>
<ul>
<li><strong>تراز اول (حصار بیرونی و دروازهٔ جنوبی):</strong> نخستین خط دفاعی قلعه که تنها مسیر باریک قابل صعود در یال جنوبی را کنترل می‌کرده و با برج‌های مدور دیده‌بانی تقویت شده است.</li>
<li><strong>تراز دوم و سوم (سربازخانه‌ها، انبارها و آب‌انبارها):</strong> فضاهای خدماتی، انبارهای ذخیرهٔ غلات و چهار آب‌انبار بزرگ دست‌کند در سنگ که با ملات ساروج عایق‌بندی شده بودند. این آب‌انبارها در فصل بارش از روان‌آب‌های سطح قله پر می‌شدند تا ساکنان دژ بتوانند ماه‌ها محاصره را در اقلیم خشک خراسان تاب بیاورند.</li>
<li><strong>تراز چهارم (ارگ مرکزی و شاه‌نشین):</strong> در بالاترین نقطهٔ قله، تالارها و اتاق شاه‌نشین با چشم‌انداز ۳۶۰ درجه بر دشت بشرویه، روستای رقه و کاروان‌روِ باستانی تون (فردوس) به طبس و اصفهان قرار دارد؛ به گونه‌ای که هیچ کاروان یا سپاهی نمی‌توانست بدون دیده‌شدن از برج‌های قلعه از این گذرگاه عبور کند.</li>
</ul>

<h2>راهنمای گام‌به‌گام صعود ایمن و عکاسی از فراز دژ</h2>
<p>مسافت پیاده‌روی از پای کوه (محل توقف خودرو در نزدیکی آسیاب آبی دهنه) تا ارگ بالایی قلعه دختر طولانی نیست، اما شیب تند و سنگریزه‌های لغزندهٔ یال جنوبی نیازمند حدود ۴۵ تا ۶۰ دقیقه صعود آرام و پیوسته است. بهترین زمان شروع صعود، ساعت ۶:۳۰ تا ۷:۳۰ صبح یا دو ساعت پیش از غروب آفتاب است. هنگام رسیدن به تراز بالای قلعه، منظرهٔ کویر، نخلستان‌ها و مزارع رقه و سایهٔ بلند کوه مخروطی قلعه دختر بر دشت پایین‌دست، کادر فوق‌العاده‌ای برای عکاسی منظره (Landscape) می‌سازد. اکیداً توصیه می‌شود حداقل دو متر از لبهٔ پرتگاه‌های شمالی، شرقی و غربی فاصله بگیرید و روی طاق‌های گچی نیمه‌ریخته پا نگذارید.</p>

<h2>فرهنگ بومی، بافت خشتی و خوراک و سوغات بشرویه</h2>
<p>پس از فرود از کوه قلعه دختر، گشت‌وگذار در بافت تاریخی شهر <a href="/city/boshruyeh/">بشرویه</a> — که یکی از سالم‌ترین بافت‌های خشتی و بادگیردار شرق ایران است و خانه‌های باشکوهی همچون <strong>خانهٔ مستوفی</strong> در آن می‌درخشد — خستگی صعود را از تنتان بیرون می‌کند.</p>
<ul>
<li><strong>خوراک‌های محلی بشرویه:</strong> <strong>آش جوش‌پره</strong>، <strong>اشکنهٔ قروت</strong>، <strong>قورمه و آبگوشت محلی</strong>، <strong>کماج و فتیر سنتی</strong> و نان‌های تنوری داغ.</li>
<li><strong>سوغات و صنایع دستی:</strong> <strong>پسته و زعفران بشرویه</strong>، <strong>عسل طبیعی</strong>، <strong>ملابافی و کرباس‌بافی</strong> (از پارچه‌های دست‌باف سنتی پنبه در بشرویه و رقه)، گلیم‌بافی و سفال محلی.</li>
</ul>

