<p><strong>تخت جمشید</strong>، یا پرسپولیس، محوطه‌ای باستانی در دشت مرودشت است که ساخت آن به فرمان داریوش اول آغاز شد و در دورهٔ شاهان هخامنشی گسترش یافت. پلکان‌های پهن، دروازهٔ ملل، تالار آپادانا و سنگ‌نگاره‌هایی که هیئت‌های گوناگون را نشان می‌دهند، اینجا را از یک مجموعهٔ کاخی فراتر می‌برند: محوطه‌ای که معماری و نمایش قدرت شاهنشاهی را در کنار هم روایت می‌کند. این اثر در <a href="/province/fars/">استان فارس</a> قرار دارد و در ۱۹۷۹ در فهرست میراث جهانی یونسکو ثبت شده است.</p>

{{GALLERY:columns}}

<h2>تخت جمشید کجاست و نام آن از کجا آمده؟</h2>
<p>محوطه در <strong>شهرستان مرودشت</strong>، در شمال‌شرقی شیراز و نزدیک شهر مرودشت قرار دارد. نام «تخت جمشید» در دوره‌های متأخر رواج یافته؛ در نوشته‌های تاریخی و پژوهش‌های مربوط به دورهٔ هخامنشی، نام‌های «پارسه» و «پرسپولیس» نیز برای این شهر و مجموعه به کار می‌روند. پرسپولیس نامی یونانی است و نباید آن را با تخت‌جمشیدِ افسانه‌ای یکی دانست؛ روایت‌های مردمی بعدها بقایای بزرگ بنا را به جمشید نسبت دادند.</p>

<h2>چرا این مجموعه ساخته شد؟</h2>
<p>بر پایهٔ اطلاعات مرکز میراث جهانی یونسکو، داریوش اول ساخت مجموعه را در حدود <strong>۵۱۸ پیش از میلاد</strong> آغاز کرد. جانشینان او، به‌ویژه خشایارشا و اردشیر اول، بخش‌هایی از بنا را افزودند. تخت جمشید یکی از مراکز مهم تشریفاتی شاهنشاهی بود؛ تراس مرتفع و مسیرهای آیینی، کاخ‌ها و نقش‌برجسته‌ها برای برگزاری مراسم و نمایش پیوند قلمروهای گوناگون با دربار هخامنشی طراحی شده بودند. محوطه در یورش اسکندر مقدونی در ۳۳۰ پیش از میلاد آسیب دید و بخش‌هایی از آن در آتش‌سوزی و ویرانی از میان رفت. دربارهٔ جزئیات و انگیزهٔ آن رخداد، منابع تاریخی روایت‌های متفاوتی دارند.</p>

<h2>در محوطه چه می‌بینیم؟</h2>
<ul>
<li><strong>پلکان ورودی:</strong> پله‌های کم‌ارتفاع و پهن، راهی تشریفاتی به صفه می‌سازند؛ روی سنگ‌ها راه بروید، اما برای عکس یا میان‌بُر از لبه‌ها و بخش‌های بسته بالا نروید.</li>
<li><strong>دروازهٔ ملل:</strong> ورودی یادمانی مجموعه با پیکره‌های نگهبان و کتیبه‌هایی که از فرمانروایی شاهان هخامنشی خبر می‌دهند.</li>
<li><strong>تالار آپادانا:</strong> بقایای تالاری ستون‌دار که از مهم‌ترین بناهای صفه است. پلکان‌های آن با ردیف‌های نقش‌برجسته آراسته شده‌اند؛ در صحنه‌ها نمایندگان سرزمین‌های مختلف پیشکش‌هایی در دست دارند.</li>
<li><strong>کاخ‌ها و نقش‌برجسته‌ها:</strong> بقایای کاخ‌های تچر و هدیش و بخش‌هایی از بناهای دیگر، تفاوت کاربرد و شیوهٔ ساخت را نشان می‌دهند. برای خواندن نقش‌ها، تابلوهای معرفی و راهنمای رسمی محوطه را دنبال کنید.</li>
<li><strong>کتیبه‌ها و سنگ‌تراشی:</strong> نوشته‌ها و جزئیات معماری را از فاصلهٔ تعیین‌شده ببینید؛ تماس دست، گچ‌نویسی یا تکیه‌دادن به آثار به سطح چندصدسالهٔ سنگ آسیب می‌زند.</li>
</ul>

{{GALLERY:griffins}}

<h2>برنامه‌ریزی بازدید</h2>
<p>برای دیدن بخش‌های اصلی دست‌کم <strong>دو تا سه ساعت</strong> وقت بگذارید. اگر قصد دارید کتیبه‌ها را بخوانید یا از راهنمای محوطه کمک بگیرید، زمان بیشتری کنار بگذارید. مسیر بازدید پیاده است و سایهٔ طبیعی کمی دارد؛ آب، کلاه، ضدآفتاب و کفش راحت همراه داشته باشید. در روزهای گرم، بازدید را به ساعات خنک‌تر موکول کنید و پیش از حرکت از بازبودن مجموعه، محدودیت‌های روز و امکان تهیهٔ بلیت مطمئن شوید؛ ساعت و تعرفه ممکن است تغییر کند.</p>

<h2>مسیر دسترسی و نکات حفاظت</h2>
<p>از شیراز در مسیر مرودشت حرکت کنید و تابلوهای محوطهٔ تخت جمشید را دنبال کنید. راه‌های دسترسی و خدمات حمل‌ونقل ممکن است با شرایط روز تغییر کنند؛ اگر با وسیلهٔ عمومی سفر می‌کنید، مسیر رفت‌وبرگشت را پیشاپیش قطعی کنید و وضعیت روز جاده و حمل‌ونقل عمومی را از سامانهٔ ملی سفر (۰۹۶۲۹) بپرسید. محوطه وسیع است و پله و اختلاف سطح دارد، بنابراین برای سالمندان یا افرادی که محدودیت حرکتی دارند، وضعیت دسترسی بخش‌های مختلف را پیش از سفر جویا شوید. از مسیرهای بسته خارج نشوید، به کتیبه‌ها دست نزنید و زباله را در محوطه رها نکنید.</p>

{{GALLERY:panorama}}

<h2>جدول راهنمای ترتیب بازدید از کاخ‌ها و بخش‌های تخت جمشید (مسیر طلایی ۳ ساعته)</h2>
<p>صفهٔ سنگی تخت جمشید در دامنهٔ غربی <strong>کوه رحمت (مهر)</strong> با مساحتی حدود ۱۲۵٬۰۰۰ متر مربع ساخته شده است<sup class="sa-cite"><a href="https://whc.unesco.org/en/list/114/">۱</a></sup>. برای آنکه در گرمای روز یا شلوغی محوطه سردرگم نشوید، ترتیب بازدید زیر را دنبال کنید:</p>
<table>
<thead><tr><th>ایستگاه بازدید</th><th>بنای شاخص</th><th>ویژگی کلیدی و نکتهٔ تماشا</th><th>زمان پیشنهادی</th></tr></thead>
<tbody>
<tr><td>ایستگاه ۱ و ۲</td><td>پلکان ورودی بزرگ و دروازهٔ ملل</td><td>۱۱۱ پلهٔ کم‌شیب تشریفاتی و گاوهای بالدار انسان‌سر (لاماسو) با کتیبهٔ سه‌زبانهٔ خشایارشا<sup class="sa-cite"><a href="https://www.britannica.com/place/Persepolis">۲</a></sup></td><td>۳۰ دقیقه</td></tr>
<tr><td>ایستگاه ۳</td><td>کاخ آپادانا و پلکان شرقی</td><td>تالار ۷۲ ستونی و شاهکار سنگ‌تراشی ۲۳ هیئت نمایندگی ملل با لباس‌ها و پیشکش‌های بومی<sup class="sa-cite"><a href="https://www.iranicaonline.org/articles/persepolis">۳</a></sup></td><td>۴۵ دقیقه</td></tr>
<tr><td>ایستگاه ۴ و ۵</td><td>کاخ تچر (آینه)، کاخ هدیش و سه‌دروازه</td><td>سنگ‌های صیقلی سیاه‌رنگ کاخ داریوش، نقش‌برجستهٔ نبرد شهریار با هیولا و پلکان کاخ شورا</td><td>۳۵ دقیقه</td></tr>
<tr><td>ایستگاه ۶ و ۷</td><td>کاخ صدستون، خزانه و موزهٔ تخت جمشید</td><td>بزرگ‌ترین تالار سرپوشیدهٔ صفه، نقش‌برجستهٔ بارعام شاهی و اشیای اصل در موزهٔ هرتسفلد</td><td>۴۵ دقیقه</td></tr>
<tr><td>ایستگاه ۸</td><td>آرامگاه‌های صخره‌ای اردشیر دوم و سوم</td><td>بر فراز دامنهٔ کوه رحمت؛ بهترین نقطه برای تماشای نقشهٔ کامل صفه و دشت <a href="/city/marvdasht/">مرودشت</a></td><td>۲۵ دقیقه</td></tr>
</tbody>
</table>

<h2>نکات طلایی عکاسی، نورپردازی و بازدید خانوادگی در تخت جمشید</h2>
<p>محوطهٔ تخت جمشید بر دامنهٔ غربی کوه رحمت ساخته شده و رو به غرب و دشت مرودشت دارد؛ همین جهت‌گیری جغرافیایی باعث می‌شود نور خورشید در ساعات مختلف روز جلوه‌ای کاملاً متفاوت به سنگ‌نگاره‌ها ببخشد:</p>
<ul>
<li><strong>نور صبحگاهی (۸ تا ۱۰:۳۰ صبح):</strong> خورشید از پشت کوه رحمت طلوع می‌کند و نور مایل صبحگاهی به بهترین شکل بر <strong>پلکان شرقی کاخ آپادانا</strong> (مشهورترین ردیف نقش‌برجستهٔ اهدای پیشکش‌های ۲۳ ملت، ارابه‌ها، شیر و گاو و گارد جاویدان) می‌تابد و سایه‌روشن عمیق و واضحی روی نقوش سنگی ایجاد می‌کند.</li>
<li><strong>نور عصرگاهی و ساعت طلایی (۱۶ تا غروب):</strong> وقتی خورشید به سمت غرب دشت مرودشت پایین می‌آید، نور طلایی مستقیم بر <strong>پلکان ورودی بزرگ، دروازهٔ ملل، ستون‌های بلند آپادانا و کاخ تچر</strong> می‌تابد. این ساعت بهترین زمان برای بالا رفتن از مسیر آرامگاه اردشیر دوم و سوم در دامنهٔ کوه رحمت و ثبت عکس پانوراما از کل صفه است.</li>
<li><strong>راهنمای صوتی، واقعیت افزوده و بازدید با کودکان و سالمندان:</strong> پیش از ورود به صفه، استفاده از راهنمای رسمی میراث فرهنگی یا راهنماهای صوتی و تصویری معتبر به شما کمک می‌کند داستان هر نقش‌برجسته را درک کنید. برای سالمندان یا خانواده‌های دارای کودک، پیشنهاد می‌شود بازدید را به ساعات خنک صبح اختصاص دهید و در میانهٔ گشت، در سایهٔ درختان نزدیک موزه استراحت و آب کافی میل کنید.</li>
</ul>

<h2>فرهنگ، خوراک محلی و سوغات شیراز و مرودشت</h2>
<p>اکثر مسافران بازدید از تخت جمشید را از مبدأ <a href="/city/shiraz/">شهرستان شیراز</a> (حدود ۵۵ کیلومتر در جنوب غربی مرودشت) آغاز می‌کنند. پس از چند ساعت پیاده‌روی در فضای باز پارسه، چشیدن طعم‌های اصیل فارس و آشنایی با صنایع دستی منطقه، لذت سفر را دوچندان می‌کند:</p>
<ul>
<li><strong>خوراک‌های محلی شیراز و مرودشت:</strong> <strong>کلم‌پلو شیرازی</strong>، <strong>شیرازی‌پلو</strong>، <strong>کوفته هلو</strong>، <strong>آش سبزی شیرازی</strong> و در وعدهٔ عصرانه <strong>فالوده شیرازی</strong> با آبلیمو یا عرق نسترن و <strong>دوغ و گوش‌فیل</strong>.</li>
<li><strong>سوغات و صنایع دستی فارس:</strong> <strong>خاتم‌کاری و منبت‌کاری شیراز</strong>، <strong>قلم‌زنی بر نقره و مس</strong>، <strong>گبه و قالی قشقایی مرودشت</strong>، <strong>مسقطی و یوخه</strong>، <strong>عرقیات گیاهی (بهارنارنج و بیدمشک)</strong> و رب انار محلی.</li>
</ul>

<h2>بازدید را با چه مقصدی همراه کنیم و چه نکات ایمنی را بدانیم؟</h2>
<p>اگر یک روز کامل در شمال شیراز وقت دارید، می‌توانید صبح زود تخت جمشید را ببینید، سپس به محوطهٔ <strong>نقش رستم و نقش رجب</strong> در ۶ کیلومتری شمال غربی صفه بروید و در صورت داشتن زمان کافی، مسیر را به سمت آرامگاه کوروش بزرگ در <a href="/city/pasargad/">شهرستان پاسارگاد</a> ادامه دهید. پیش از پیاده‌روی طولانی در این محوطه‌های باستانی روباز، راهنماهای <a href="/heatstroke-first-aid/">پیشگیری از گرمازدگی</a>، <a href="/camping-water-planning/">همراه داشتن آب کافی</a>، <a href="/ankle-sprain-first-aid/">انتخاب کفش مناسب پیاده‌روی</a> و <a href="/choosing-campsite/">اخلاق گردشگری و حفاظت از میراث</a> را مرور کنید. همچنین برای آشنایی با دیگر شاهکارهای ثبت‌شده در میراث جهانی یونسکو و بناهای تاریخی ایران، راهنمای <a href="/attraction/naqsh-e-jahan-square-isfahan/">میدان نقش جهان</a> در اصفهان، <a href="/attraction/fin-garden/">باغ فین کاشان</a> و <a href="/attraction/falak-ol-aflak-castle-khorramabad/">قلعه فلک‌الافلاک خرم‌آباد</a> را ببینید.</p>
