{{GALLERY:panorama}}

<h2>میدان نقش جهان کجاست؟</h2>
<p>میدان در قلب بافت تاریخی اصفهان و در <a href="/city/isfahan-city/">شهرستان اصفهان</a> قرار دارد. پیرامون آن، بازارها و گذرهای قدیمی به خیابان‌های مرکزی شهر می‌رسند؛ به همین دلیل بازدید از میدان را می‌توان با پیاده‌روی در بافت تاریخی همراه کرد. نام «میدان نقش جهان» در گفتار روزمره رایج است؛ در اسناد ثبت جهانی یونسکو، نام «Meidan Emam, Esfahan» آمده و پیش‌تر نیز میدان شاه خوانده می‌شد.</p>

<h2>چگونه میدان صفوی شکل گرفت؟</h2>
<p>در آغاز سدهٔ هفدهم میلادی، شاه عباس اول پایتخت صفوی را به اصفهان منتقل کرد و مرکز تازهٔ شهر با میدان، محورهای بازار و بناهای حکومتی سامان یافت. میدان هم جای گردهمایی و دادوستد بود و هم صحنهٔ آیین‌ها و رویدادهای عمومی. رواق‌های پیرامونی، پیوند میان حجره‌ها و فضای باز را برقرار می‌کنند و چهار بنای اصلی هر کدام نقشی متفاوت دارند: نیایش، پذیرایی و حکومت، بازار و دسترسی به شبکهٔ تجاری شهر.</p>

<h2>چهار سوی میدان؛ چهار تجربهٔ متفاوت</h2>
<ul>
<li><strong>مسجد امام:</strong> بنایی در ضلع جنوبی که با سردر بلند، کاشی‌کاری و گنبدش شناخته می‌شود. این مسجد را گاه مسجد شاه نیز می‌نامند؛ برای بازدید، پوشش و مقررات مذهبی محل را رعایت کنید.</li>
<li><strong>مسجد شیخ لطف‌الله:</strong> در ضلع شرقی میدان قرار دارد و به گنبد و تزیینات کاشی‌کاری‌اش شهرت دارد. کاربری و دسترسی آن با مسجد جامعِ عمومی یکی نیست؛ ساعت ورود را پیش از برنامه‌ریزی بررسی کنید.</li>
<li><strong>عمارت عالی‌قاپو:</strong> در ضلع غربی، رو به میدان؛ کاخی چندطبقه که از آن برای تشریفات و پذیرایی درباری استفاده می‌شد. پله‌ها و فضاهای داخلی ممکن است برای همهٔ بازدیدکنندگان دسترس‌پذیر نباشد.</li>
<li><strong>سردر بازار قیصریه:</strong> در ضلع شمالی، ورودی بازار تاریخی است. بازار را می‌توان در ادامهٔ گشت دید، اما ساعت فعالیت حجره‌ها و راسته‌ها با ساعات بازدید از میدان یکسان نیست.</li>
</ul>

{{GALLERY:portal}}

<h2>برنامهٔ پیشنهادی گشت</h2>
<p>برای گردش در میدان و دیدن نمای بیرونی چهار بنا حدود <strong>دو تا سه ساعت</strong> در نظر بگیرید. اگر قصد ورود به همهٔ بناها را دارید، برنامه را به نیم‌روز گسترش دهید و ساعت بازدید و زمان استراحت را جداگانه بسنجید. می‌توانید از سردر قیصریه آغاز کنید، در امتداد رواق‌ها حرکت کنید و در هر ضلع برای دیدن جزئیات معماری توقف داشته باشید. صبح زود یا عصر معمولاً برای پیاده‌روی دلپذیرتر است؛ در میانهٔ روزهای گرم، سایه و آب در دسترس را از قبل در نظر بگیرید.</p>

<h2>دسترسی و نکات بازدید</h2>
<p>به‌دلیل قرارگرفتن میدان در بافت مرکزی، مسیر خودرویی و محل توقف ممکن است با محدودیت ترافیکی یا رویدادهای شهری تغییر کند. استفاده از حمل‌ونقل شهری و ادامهٔ مسیر پیاده‌روی می‌تواند ساده‌تر باشد؛ مسیر روز را از نقشه و اطلاعیه‌های محلی بررسی کنید. فضای عمومی میدان با داخل بناها تفاوت دارد: ساعت‌ها و بلیت‌ها جدا هستند و ممکن است در مناسبت‌ها تغییر کنند. در ساعات شلوغ از وسایل شخصی مراقبت کنید، مراقب کودکان باشید و هنگام عکاسی یا ورود به مسجدها به حریم نمازگزاران احترام بگذارید.</p>

{{GALLERY:hall}}

<h2>جدول مقایسهٔ چهار ضلع تاریخی میدان نقش جهان (میراث جهانی یونسکو)</h2>
<p>میدان نقش جهان با طول حدود ۵۶۰ متر و عرض ۱۶۰ متر (مساحتی نزدیک به ۹ هکتار)، از نخستین نمونه‌های طراحی شهری یکپارچه در عصر صفوی است که در سال ۱۹۷۹ میلادی به شمارهٔ ۱۱۵ در فهرست میراث جهانی یونسکو ثبت شد<sup class="sa-cite"><a href="https://whc.unesco.org/en/list/115/">۱</a></sup>. جدول زیر به شما کمک می‌کند زمان بازدید خود را میان چهار ضلع میدان تقسیم کنید:</p>
<table>
<thead><tr><th>ضلع میدان</th><th>بنای شاخص</th><th>معمار / دورهٔ ساخت</th><th>نکتهٔ طلایی بازدید و عکاسی</th></tr></thead>
<tbody>
<tr><td>ضلع جنوبی</td><td>مسجد جامع عباسی (مسجد امام / شاه)</td><td>استاد علی‌اکبر اصفهانی (آغاز ۱۶۱۱ م)<sup class="sa-cite"><a href="https://www.iranicaonline.org/articles/isfahan-x-monuments-2-the-meydan-e-sah">۲</a></sup></td><td>پژواک صدا در نقطهٔ کانونی زیر گنبد دوپوسته و چرخش ۴۵ درجه‌ای به سوی قبله</td></tr>
<tr><td>ضلع شرقی</td><td>مسجد شیخ لطف‌الله</td><td>استاد محمدرضا اصفهانی (۱۶۰۳ تا ۱۶۱۹ م)</td><td>مسجد اختصاصی بدون مناره و صحن؛ بازی نور خورشید و طرح «طاووس» در مرکز گنبد نخودی‌رنگ</td></tr>
<tr><td>ضلع غربی</td><td>عمارت шести‌طبقهٔ عالی‌قاپو</td><td>دورهٔ شاه عباس اول و الحاق ایوان در دورهٔ شاه عباس دوم</td><td>ایوان ستون‌دار مشرف به میدان و «تالار موسیقی» در طبقهٔ ششم با مقرنس‌های توخالی آکوستیک<sup class="sa-cite"><a href="https://www.britannica.com/place/Isfahan-Iran">۳</a></sup></td></tr>
<tr><td>ضلع شمالی</td><td>سردر قیصریه و بازار بزرگ</td><td>اوایل قرن هفدهم میلادی (دورهٔ صفوی)</td><td>نگاره‌های شکارگاه صفوی و نماد برج قوس (کماندار اصفهان) بر سردر و ورود به راستهٔ چایخانه‌ها و کارگاه‌ها</td></tr>
</tbody>
</table>

<h2>بهترین ساعت‌های روز برای عکاسی و تجربهٔ زندهٔ میدان نقش جهان</h2>
<p>میدان نقش جهان در هر ساعت از شبانه‌روز چهره و نوری متفاوت دارد. اگر می‌خواهید هم شکوه معماری صفوی را بدون ازدحام ثبت کنید و هم زندگی جاری شهر را تجربه نمایید، زمان‌بندی زیر را در نظر بگیرید:</p>
<ul>
<li><strong>ساعت ۷:۳۰ تا ۱۰:۰۰ صبح (نور طلایی بر عالی‌قاپو و ورود به شیخ لطف‌الله):</strong> در ابتدای صبح، میدان خلوت و آرام است، خورشید از شرق می‌تابد و نمای ایوان ستون‌دار عمارت عالی‌قاپو را به زیبایی روشن می‌کند. همچنین در این ساعت، پرتو خورشید از پنجره‌های مشبک گلویی گنبد مسجد شیخ لطف‌الله به درون شبستان می‌تابد و طرح مشهور «طاووس نور» را در مرکز سقف گنبد کامل می‌سازد.</li>
<li><strong>ساعت ۱۱:۰۰ تا ۱۴:۳۰ ظهر (بازار قیصریه و کارگاه‌های صنایع دستی):</strong> هنگامی که آفتاب در فضای باز میدان تندتر می‌شود، بهترین زمان برای رفتن به زیر طاق‌های خنک سردر قیصریه، بازار بزرگ اصفهان، کارگاه‌های قلم‌زنی و قلمکار و صرف بریانی یا ناهار سنتی در سفره‌خانه‌های تاریخی اطراف میدان است.</li>
<li><strong>ساعت ۱۶:۳۰ تا ساعت آبی پس از غروب (مسجد امام و پانورامای شبانه):</strong> در عصرگاه، نور گرم آفتاب بر کاشی‌های هفت‌رنگ سردر مسجد شیخ لطف‌الله و سردر مسجد امام می‌نشیند، درشکهها در گرداگرد میدان حرکت می‌کنند و خانواده‌های اصفهانی کنار حوض بزرگ جمع می‌شوند. بیست دقیقه پس از غروب آفتاب («ساعت آبی» / Blue Hour)، زمانی که چراغ‌های رواق‌های دوطبقه و گنبدها روشن می‌شوند و آسمان هنوز لاجوردی است، از ایوان عالی‌قاپو یا ضلع شمالی میدان می‌توانید زیباترین عکس‌های پانورامای میدان نقش جهان را ثبت کنید.</li>
</ul>

<h2>فرهنگ بازارگردی، خوراک سنتی و سوغات و صنایع دستی میدان نقش جهان</h2>
<p>بخشی از روح زندهٔ میدان نقش جهان، صدای چکش استادکاران مسگر و قلم‌زن در حجره‌های دورادور میدان و عطر چای دارچین و بریانی در گذرهای بازار قیصریه است:</p>
<ul>
<li><strong>خوراک‌ها و طعم‌های اصیل اصفهان در اطراف میدان:</strong> <strong>بریانی (بریون) اصفهان</strong> با نان سنگک و دوغ محلی، <strong>خورشت ماست زعفرانی</strong> (دسر اصیل اصفهانی)، <strong>حلیم بادمجان</strong>، <strong>کباب و دوغ و گوش‌فیل</strong> و <strong>فرنی و شیره</strong> در چایخانه‌های سنتی سردر قیصریه.</li>
<li><strong>صنایع دستی و سوغات:</strong> <strong>میناکاری روی مس</strong>، <strong>خاتم‌کاری</strong>، <strong>قلم‌زنی</strong>، <strong>فیروزه‌کوبی</strong>، <strong>پارچه‌های قلمکار</strong> (چاپ دستی با مهر چوبی)، <strong>گز آردی و لقمه‌ای با مغز پسته</strong> و <strong>پولکی و نبات زعفرانی</strong>. هنگام خرید صنایع دستی، به مهر اصالت استادکار و وزن و کیفیت زیرساخت مسی دقت کنید.</li>
</ul>

<h2>یک اثر ثبت جهانی دیگر و ادامهٔ سفر در مرکز ایران</h2>
<p>برای آشنایی با یکی دیگر از آثار ایرانیِ ثبت‌شده در فهرست میراث جهانی، راهنمای <a href="/attraction/persepolis-takht-jamshid/">تخت جمشید</a> را بخوانید؛ آن محوطه در استان فارس است و بازدید از آن برنامهٔ سفری جداگانه می‌خواهد. همچنین در ادامهٔ سفر در محور شمال به جنوب استان، بازدید از <a href="/attraction/fin-garden/">باغ فین کاشان</a> در <a href="/city/kashan/">کاشان</a>، بافت تاریخی <a href="/city/natanz/">شهرستان نطنز</a> و <a href="/city/shahreza/">شهرضا</a> را در برنامه بگذارید و برای سفر مسئولانه، راهنمای <a href="/choosing-campsite/">اخلاق گردشگری و حفاظت از میراث</a> را مرور کنید.</p>
